comms.text:
@1 וּנְפַק יַעֲקֹב מִבְּאֵרָא דְשָׁבַע וַאֲזַל לְחָרָן:
@2 וַעֲרַע בְּאַתְרָא וּבָת תַּמָּן אֲרֵי עָל שִׁמְשָׁא וּנְסִיב מֵאַבְנֵי אַתְרָא וְשַׁוִּי אִסָדוֹהִי וּשְׁכִיב בְּאַתְרָא הַהוּא:
@3 וַחֲלַם וְהָא סֻלְמָא נָעִיץ בְּאַרְעָא וְרֵישֵׁהּ מָטֵי עַד צֵית שְׁמַיָּא וְהָא מַלְאָכַיָּא דַּיְיָ סָלְקִין וְנָחֲתִין בֵּהּ:
@4 וְהָא יְקָרָא דַיְיָ מְעַתַּד עִלָווֹהִי וַאֲמַר אֲנָא יְיָ אֱלָהֵהּ דְּאַבְרָהָם אָבוּךְ וֵאלָהֵהּ דְּיִצְחָק אַרְעָא דִּי אַתְּ שְׁכִיב עֲלַהּ לָךְ אֶתְּנִנַּהּ וְלִבְנָיךְ:
@5 וִיהוֹן בְּנָיךְ סַגִּיאִין כְּעַפְרָא דְאַרְעָא וְתִתְקֵף לְמַעַרְבָא וּלְמַדִינְחָא וּלְצִפּוּנָא וּלְדָרוֹמָא וְיִתְבָּרְכוּן בְּדִילָךְ כָּל זַרְעֲיַת אַרְעָא וּבְדִיל בְּנָיךְ:
@6 וְהָא מֵימְרִי בְּסַעְדָךְ וְאֶטְרִנָךְ בְּכָל אֲתַר דִּי תְהַךְ וַאֲתֵיבִנָּךְ לְאַרְעָא הָדָא אֲרֵי לָא אֶשְׁבְּקִנָּךְ עַד דִּי אֶעְבֵּיד יָת דִּי מַלֵּלִית לָךְ:
@7 וְאִתְּעַר יַעֲקֹב מִשִּׁנְתֵּהּ וַאֲמַר בְּקוּשְׁטָּא (אִית) יְקָרָא דַיְיָ שָׁרֵי בְּאַתְרָא הָדֵין וַאֲנָא לָא הֲוֵיתִי יְדָע:
@8 וּדְחִיל וַאֲמַר מָה דְחִילוּ אַתְרָא הָדֵין לֵית דֵּין אֲתַר הֶדְיוֹט אֶלָהֵין אֲתַר דְּרַעֲוָא בֵהּ מִן קֳדָם יְיָ וְדֵין תְּרַע קֳבֵל שְׁמַיָּא:
@9 וְאַקְדֵים יַעֲקֹב בְּצַפְרָא וּנְסִיב יָת אַבְנָא דִי שַׁוִּי אִסָדוֹהִי וְשַׁוִּי יָתַהּ קָמָא וַאֲרִיק מִשְׁחָא עַל רֵישֵׁהּ:
@10 וּקְרָא יָת שְׁמָא דְאַתְרָא הַהוּא בֵּית אֵל וּבְרַם לוּז שְׁמָא דְקַרְתָּא בְּקַדְמֵיתָא:
@11 וְקַיִּים יַעֲקֹב קְיָם לְמֵימָר אִם יְהֵא מֵימְרָא דַּיְיָ בְּסַעְדִי וְיִטְרִינַנִּי בְּאָרְחָא הָדֵין דִּי אֲנָא אָזֵל וְיִתֶּן לִי לַחֲמָא (נ''י לְחֵם) לְמֵיכַל וּכְסוּ לְמִלְבָּשׁ:
@12 וְאֵתוּב בִּשְׁלַם לְבֵית אַבָּא וִיהֵא מֵימְרָא דַיְיָ לִי לֵאלָהָא:
@13 וְאַבְנָא הָדָא דִי שַׁוֵּיתִי קָמָא תְּהֵי דִי אֵהֵי פָלַח עֲלַהּ קֳדָם יְיָ וְכֹל דִּי תִתֶּן לִי חַד מִן עַשְׂרָא אַפְרְשִׁנֵּהּ קֳדָמָךְ:
@14 וּנְטַל יַעֲקֹב רַגְלוֹהִי (נ''י רִיגְלוֹהִי) וַאֲזַל לַאֲרַע בְּנֵי מַדִינְחָא:
@15 וַחֲזָא וְהָא בֵירָא בְחַקְלָא וְהָא תַמָּן תְּלָתָא עֶדְרִין דְּעָן רְבֵעִין עֲלַהּ אֲרֵי מִן בֵּירָא הַהִיא מַשְׁקָן עֲדָרַיָּא וְאַבְנָא רַבְּתָא עַל פּוּמָא דְבֵירָא:
@16 וּמִתְכַּנְשִׁין לְתַמָּן כָּל עֲדָרַיָּא וּמְגַנְדְּרִין יָת אַבְנָא מֵעַל פּוּמָא דְבֵירָא וּמַשְׁקָן יָת עָנָא וּמְתִיבִין יָת אַבְנָא עַל פּוּמָא דְבֵירָא לְאַתְרַהּ:
@17 וַאֲמַר לְהוֹן יַעֲקֹב אַחַי מְנָן אַתּוּן וַאֲמָרוּ מֵחָרָן אֲנָחְנָא:
@18 וַאֲמַר לְהוֹן הַיְדַעְתּוּן יָת לָבָן בַּר נָחוֹר וַאֲמָרוּ יְדַעְנָן:
@19 וַאֲמַר לְהוֹן הַשְׁלַם לֵהּ וַאֲמָרוּ שְׁלַם וְהָא רָחֵל בְּרַתֵּהּ אַתְיָא עִם עָנָא:
@20 וַאֲמַר הָא עוֹד יוֹמָא סַגִי לָא עִדַן לְמִכְנַשׁ בְּעִיר אַשְׁקוּ עָנָא וְאִזִילוּ רְעוּ:
@21 וַאֲמָרוּ לָא נִכּוּל עַד דִי יִתְכַּנְשִׁין כָּל עֲדָרַיָּא וִיגַנְדְרוּן יָת אַבְנָא מֵעַל פוּמָא דְבֵירָא וְנַשְׁקֵי עָנָא:
@22 עַד דְהוּא מְמַלֵל עִמְהוֹן וְרָחֵל אָתַת עִם עָנָא דִי לַאֲבוּהָ אֲרֵי רָעִיתָא הִיא:
@23 וַהֲוָה כַּד חֲזָא יַעֲקֹב יָת רָחֵל בַּת לָבָן אֲחוּהָא דְאִמֵהּ וְיָת עָנָא דְלָבָן אֲחוּהָא דְאִמֵהּ וּקְרֵב יַעֲקֹב וּגַנְדַר יָת אַבְנָא מֵעַל פּוּמָא דְבֵירָא וְאַשְׁקֵי יָת עָנָא דְלָבָן אֲחוּהָא דְאִמֵהּ:
@24 וּנְשַׁק יַעֲקֹב לְרָחֵל וַאֲרֵם יָת קָלֵהּ וּבְכָא:
@25 וְחַוִּי יַעֲקֹב לְרָחֵל אֲרֵי בַר אֲחַת אָבוּהָא הוּא וַאֲרֵי בַר רִבְקָה הוּא וּרְהָטַת וְחַוִּיאַת לְאָבוּהָא:
@26 וַהֲוָה כַּד שְׁמַע לָבָן יָת שֵׁמַע יַעֲקֹב בַּר אֲחָתֵהּ וּרְהַט לְקַדָמוּתֵהּ וְגַפֵּף לֵהּ וְנַשִׁיק לֵהּ וְאַעֲלֵהּ לְבֵיתֵהּ וְאִשְׁתָּעִי לְלָבָן יָת כָּל פִּתְגָמַיָּא הָאִלֵּין:
@27 וַאֲמַר לֵהּ לָבָן בְּרַם קָרִיבִי וּבִשְׂרִי אָתְּ וִיתֵיב עִמֵּהּ יְרַח יוֹמִין:
@28 וַאֲמַר לָבָן לְיַעֲקֹב הֲמִדְּאָחִי אַתְּ וְתִפְלְחִנַּנִּי מַגָּן חַוִּי לִי מָה אַגְרָךְ:
@29 וּלְלָבָן תַּרְתֵּין בְּנָן שׁוּם רַבְּתָא לֵאָה וְשׁוּם זְעֶרְתָּא רָחֵל:
@30 וְעֵינֵי לֵאָה יָאֲיָן וְרָחֵל הֲוַת שַׁפִּירָא בְרֵיוָא וְיָאֲיָא בְחֶזְוָא:
@31 וּרְחֵם יַעֲקֹב יָת רָחֵל וַאֲמַר אֶפְלְחִנָּךְ שְׁבַע שְׁנִין בְּרָחֵל בְּרַתָּךְ זְעֶרְתָּא:
@32 וַאֲמַר לָבָן טַב דְּאֶתֵּן יָתַהּ לָךְ מִדְּאֶתֵּן יָתַהּ לִגְבַר אָחֳרָן תִּיב עִמִּי:
@33 וּפְלַח יַעֲקֹב בְּרָחֵל שְׁבַע שְׁנִין וַהֲווֹ בְעֵינוֹהִי כְּיוֹמִין זְעִירִין כַּד רְחֵים יָתַהּ:
@34 וַאֲמַר יַעֲקֹב לְלָבָן הַב יָת אִתְּתִי אֲרֵי אַשְׁלֵמִית יוֹמֵי פָלְחָנִי וְאֵעוֹל לְוָתַהּ:
@35 וּכְנַשׁ לָבָן יָת כָּל אֲנָשֵׁי אַתְרָא וַעֲבַד מִשְׁתְּיָא:
@36 וַהֲוָה בְרַמְשָׁא וּדְבַר יָת לֵאָה בְרַתֵּהּ וְאָעֵיל יָתַהּ לְוָתֵהּ וְעַל לְוָתַהּ:
@37 וִיהַב לָבָן לַהּ יָת זִלְפָּה אַמְתֵהּ לְלֵאָה בְרַתֵּהּ לְאַמְהוּ:
@38 וַהֲוָה בְצַפְרָא וְהָא הִיא לֵאָה וַאֲמַר לְלָבָן מָה דָּא עֲבַדְתָּ לִּי הֲלָא בְרָחֵל פְּלָחִית עִמָּךְ וּלְמָא שַׁקַּרְתָּ בִּי:
@39 וַאֲמַר לָבָן לָא יִתְעֲבֵד כְּדֵין בְּאַתְרָנָא לְמִתַּן זְעֶרְתָּא קֳדָם רַבְּתָא:
@40 אַשְׁלִים שְׁבוּעֲתָא דְדָא וְנִתֵּן לָךְ אַף יָת דָּא בְּפָלְחָנָא דִּי תִפְלַח עִמִּי עוֹד שְׁבַע שְׁנִין אָחֳרָנִין:
@41 וַעֲבַד יַעֲקֹב כֵּן וְאַשְׁלֵים שְׁבוּעֲתָא דְדָא וִיהַב לֵהּ יָת רָחֵל בְּרַתֵּהּ לֵהּ לְאִנְתּוּ:
@42 וִיהַב לָבָן לְרָחֵל בְּרַתֵּהּ יָת בִּלְהָה אַמְתֵהּ לַהּ לְאַמְהוּ:
@43 וְעַל אַף לְּוַת רָחֵל וּרְחֵים אַף יָת רָחֵל מִלֵּאָה וּפְלַח עִמֵּהּ עוֹד שְׁבַע שְׁנִין אָחֳרָנִין:
@44 וַחֲזָא יְיָ אֲרֵי שְׂנִיאֲתָא לֵאָה וִיהַב לַהּ עִדּוּי וְרָחֵל עַקְרָא:
@45 וְעַדִּיאַת לֵּאָה וִילִידַת בָּר וּקְרַת שְׁמֵהּ רְאוּבֵן אֲרֵי אֲמֶרֶת אֲרֵי גְלִי קֳדָם יְיָ עֻלְבּוֹנִי אֲרֵי כְעַן יְרַחֲמִנַנִי בַעֲלִי:
@46 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת אֲרֵי שְׁמִיעַ קֳדָם יְיָ אֲרֵי שְׂנִיאֲתָא אֲנָא וִיהַב לִי אַף יָת דֵּין וּקְרַת שְׁמֵהּ שִׁמְעוֹן:
@47 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת הָדָא זִמְנָא יִתְחַבַּר לִי בַעֲלִי אֲרֵי יְלֵידִית לֵהּ תְּלָתָא בְנִין עַל כֵּן קְרָא שְׁמֵהּ לֵוִי:
@48 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת הָדָא זִמְנָא אוֹדֶה קֳדָם יְיָ עַל כֵּן קְרַת שְׁמֵהּ יְהוּדָה וְקָמַת מִלְּמֵילַד:
@49 וַחֲזַת רָחֵל אֲרֵי לָא יְלִידַת לְיַעֲקֹב וְקַנִּיאַת רָחֵל בַּאֲחָתַהּ וַאֲמֶרֶת לְיַעֲקֹב הַב לִי בְנִין וְאִם לָא מֵיתָא אֲנָא:
@50 וּתְקֵיף רוּגְזָא דְיַעֲקֹב בְּרָחֵל וַאֲמַר הָא מִנִּי אַתְּ בַּעְיָא הֲלָא מִן קֳדָם יְיָ תִּבְעִין דִּי מְנַע מִנִּיךְ וַלְדָא דִּמְעִין:
@51 וַאֲמֶרֶת הָא אַמְתִי בִלְהָה עוּל לְוָתַהּ וּתְלִיד וַאֲנָא אֱרַבֵּי וְאִתְבְּנֵי אַף אֲנָא מִנַּהּ:
@52 וִיהָבַת לֵהּ יָת בִּלְהָה אַמְתַהּ לְאִנְתּוּ וְעַל לְוָתַהּ יַעֲקֹב:
@53 וְעַדִּיאַת בִּלְהָה וִילִידַת לְיַעֲקֹב בַּר:
@54 וַאֲמֶרֶת רָחֵל דְּנַנִּי יְיָ וְאַף קַבִּיל צְלוֹתִי וִיהַב לִי בַּר עַל כֵּן קְרַת שְׁמֵהּ דָּן:
@55 וְעַדִּיאַת עוֹד וִילִידַת בִּלְהָה אַמְתָא דְרָחֵל בָּר תִּנְיָן לְיַעֲקֹב:
@56 וַאֲמֶרֶת רָחֵל קַבִּיל יְיָ בָּעוּתִי בְּאִתְחַנָּנוּתִי בִּצְלוֹתִי חֲמֵידַת דִּיהֵי לִי וְלַד כַּאֲחָתִי אַף אִתְיְהִיב לִי וּקְרַת שְׁמֵהּ נַפְתָּלִי:
@57 וַחֲזַת לֵּאָה אֲרֵי קָמַת מִלְּמֵילַד וּדְבָרַת יָת זִלְפָּה אַמְתַהּ וִיהָבַת יָתַהּ לְיַעֲקֹב לְאִנְתּוּ:
@58 וִילִידַת זִלְפָּה אַמְתָא דְלֵאָה לְיַעֲקֹב בָּר:
@59 וַאֲמֶרֶת לֵאָה אֲתָא גָד וּקְרַת יָת שְׁמֵהּ גָּד:
@60 וִילִידַת זִלְפָּה אַמְתָא דְלֵאָה בָּר תִּנְיָן לְיַעֲקֹב:
@61 וַאֲמֶרֶת לֵאָה תֻּשְׁבַּחְתָּא הֲוַת לִי אֲרֵי בְכֵן יְשַׁבְּחֻנַּנִּי נְשַׁיָּא וּקְרַת יָת שְׁמֵהּ אָשֵׁר:
@62 וַאֲזַל רְאוּבֵן בְּיוֹמֵי חֲצַד חִטִּין וְאַשְׁכַּח יַבְרוּחִין בְּחַקְלָא וְאַיְתִי יָתְהוֹן לְלֵאָה אִמֵּהּ וַאֲמֶרֶת רָחֵל לְלֵאָה הָבִי כְעַן לִי מִיַּבְרוּחֵי דִּבְרִיךְ:
@63 וַאֲמֶרֶת לַהּ הַזְעֵיר דִּדְבַרְתְּ יָת בַּעְלִי וְתִסְּבִין אַף יָת יַבְרוּחֵי דִּבְרִי וַאֲמֶרֶת רָחֵל בְּכֵן יִשְׁכּוּב עִמָּךְ בְּלֵילְיָא חֳלַף יַבְרוּחֵי דִּבְרִיךְ:
@64 וַאֲתָא (נ''י וְעַל) יַעֲקֹב מִן חַקְלָא בְּרַמְשָׁא וּנְפָקַת לֵאָה לְקַדָּמוּתֵהּ וַאֲמֶרֶת לְוָתִי תֵיעוֹל אֲרֵי מֵיגַר אֲגַרְתִּיךְ בְּיַבְרוּחֵי דִּבְרִי וּשְׁכִיב עִמַּהּ בְּלֵילְיָא הוּא:
@65 וְקַבִּיל יְיָ צְלוֹתַהּ דְּלֵאָה וְעַדִּיאַת וִילִידַת לְיַעֲקֹב בַּר חֲמִישָׁאֵי:
@66 וַאֲמֶרֶת לֵאָה יְהַב יְיָ אַגְרִי דִּי יְהָבִית אַמְתִי לְבַעְלִי וּקְרַת שְׁמֵהּ יִשָּׂשׂכָר:
@67 וְעַדִּיאַת עוֹד לֵאָה וִילִידַת בַּר שְׁתִיתָאֵי לְיַעֲקֹב:
@68 וַאֲמֶרֶת לֵאָה יְהַב יְיָ יָתֵהּ לִי חָלַק טַב הָדָא זִמְנָא יְהֵי מְדוֹרֵהּ דְּבַעְלִי לְוָתִי אֲרֵי יְלֵידִית לֵהּ שִׁתָּא בְנִין וּקְרַת יָת שְׁמֵהּ זְבֻלוּן:
@69 וּבָתַר כֵּן יְלִידַת בְּרַתָּא וּקְרַת יָת שְׁמַהּ דִּינָה:
@70 וְעַל דּוּכְרָנָא דְרָחֵל קֳדָם יְיָ וְקַבִּיל צְלוֹתַהּ יְיָ וִיהַב לַהּ עִדּוּי:
@71 וְעַדִּיאַת וִילִידַת בָּר וַאֲמֶרֶת כְּנַשׁ יְיָ יָת חִסּוּדִי:
@72 וּקְרַת יָת שְׁמֵהּ יוֹסֵף לְמֵימָר יוֹסֵף יְיָ לִי בַּר אָחֳרָן:
@73 וַהֲוָה כַּד יְלִידַת רָחֵל יָת יוֹסֵף וַאֲמַר יַעֲקֹב לְלָבָן שַׁלְּחַנִּי וְאֵיהַךְ לְאַתְרִי וּלְאַרְעִי:
@74 הַב יָת נְשַׁי וְיָת בְּנַי דִּי פְלָחִית יָתָךְ בְּהֵן וְאֵזִיל אֲרֵי אַתְּ יְדַעְתָּ יָת פָּלְחָנִי דִּי פְלָחִתָּךְ:
@75 וַאֲמַר לֵהּ לָבָן אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ נַסֵּיתִי וּבָרְכַנִי יְיָ בְּדִילָךְ:
@76 וַאֲמָר פָּרֵישׁ אַגְרָךְ עֲלַי וְאֶתֵּן:
@77 וַאֲמַר לֵהּ אַתְּ יְדַעְתָּ יָת דִּי פְלָחִתָּךְ וְיָת דַּהֲוָה בְעִירָךְ עִמִּי:
@78 אֲרֵי זְעֵיר דִּי הֲוָה לָךְ קֳדָמַי וּתְקֵיף לְמִסְגֵּי וּבְרִיךְ יְיָ יָתָךְ בְּדִילִי וּכְעַן אֵימָתַי אֶעְבֵּיד אַף אֲנָא לְבֵיתִי:
@79 וַאֲמַר מָה אֶתֵּן לָךְ וַאֲמַר יַעֲקֹב לָא תִתֶּן לִי מִדַּעַם אִם תַּעְבֶּד לִי פִּתְגָּמָא הָדֵין אֱתוּב אֶרְעֵי עָנָךְ אֶטָּר:
@80 אֶעְבַּר בְּכָל עָנָךְ יוֹמָא דֵּין הַעֲדֵי (נ''י אַעְדִּי) מִתַּמָּן כָּל אִמָּר נְמוֹר וּרְקוֹעַ וְכָל אִמָּר שְׁחוּם בְּאִמְרַיָא וּרְקוֹעַ וּנְמוֹר בְּעִזַיָא וִיהֵי אַגְרִי:
@81 וְתַסְהֵד בִּי זָכוּתִי בְּיוֹם דִּמְחָר אֲרֵי תֵיעוֹל עַל אַגְרִי קֳדָמָךְ כֹּל דִּי לֵיתוֹהִי נְמוֹר וּרְקוֹעַ בְּעִזַּיָּא וּשְׁחוּם בְּאִמְרַיָא גְּנוּבָא הוּא עִמִּי:
@82 וַאֲמַר לָבָן בְּרַם לְוַי יְהֵי כְפִתְגָּמָךְ:
@83 וְאַעְדִּי בְיוֹמָא הַהוּא יָת תְּיָשַׁיָא רְגוֹלַיָא וּרְקוֹעַיָא וְיָת כָּל עִזַּיָא נְמוֹרְתָא וּרְקוֹעֲתָא כֹּל דִּי חִוָּר בֵּהּ וְכָל דִּשְׁחוּם בְּאִמְּרַיָּא וִיהַב בְּיַד בְּנוֹהִי:
@84 וְשַׁוִּי מַהֲלַךְ תְּלָתָא יוֹמִין בֵּינוֹהִי וּבֵין יַעֲקֹב וְיַעֲקֹב רָעֵי יָת עָנָא דְלָבָן דְּאִשְׁתָּאֳרָן:
@85 וּנְסִיב לֵהּ יַעֲקֹב חוּטְרִין דִּלְבָן רַטִּיבִין וִּדְלוּז וְדִדְלוּף וְקַלִּיף בְּהוֹן קִלְפִין חִוָּרִין קִלּוּף חִוָּר דִּי עַל חוּטְרַיָּא:
@86 וְדָעִיץ יָת חוּטְרַיָּא דִּי קַלִּיף בִּרְהָטַיָּא אֲתַר בֵּית שַׁקְיָא דְמַיָּא אֲתַר דְּאָתָן (נ''י דְּאָתְיָן) עָנָא לְמִשְׁתֵּי לְקִבְלֵיהוֹן דְּעָנָא וּמִתְיַחֲמָן בְּמֵיתֵיהוֹן לְמִשְׁתֵּי:
@87 וְאִתְיַחֲמָא עָנָא בְּחוּטְרַיָּא וִילִידָא עָנָא רְגוֹלִין נְמוֹרִין וּרְקוֹעִין:
@88 וְאִמְּרַיָּא אַפְרֵשׁ יַעֲקֹב וִיהַב בְּרֵישׁ עָנָא כָּל דִּרְגוֹל וְכָל דִּשְׁחוּם בְּעָנָא דְלָבָן וְשַׁוִּי לֵהּ עֶדְרִין בִּלְחוֹדוֹהִי וְלָא עֲרֵבִנּוּן עִם עָנָא דְלָבָן:
@89 וַהֲוֵי בְּכָל עִדַּן דְּמִתְיַחֲמָן עָנָא מְבַכַּרְתָּא וּמְשַׁוִּי יַעֲקֹב יָת חוּטְרַיָּא לְעֵינֵי עָנָא בִּרְהָטַיָּא לְיַחָמוּתְהוֹן בְּחוּטְרַיָּא:
@90 וּבְלַקִּישׁוּת עָנָא לָא מְשַׁוֵּי וַהֲווֹ לַקִּישָׁא לְלָבָן וּבַכִּירַיָּא לְיַעֲקֹב:
@91 וּתְקֵיף גַּבְרָא לַחֲדָא לַחֲדָא וַהֲווֹ לֵהּ עָן סַגִּיאָן וְאַמְהָן וְעַבְדִּין וְגַמְלִין וַחֲמָרִין:
@92 וּשְׁמַע יָת פִתְגָּמֵי בְנֵי לָבָן דְּאָמְרִין נְסִיב יַעֲקֹב יָת כָּל דִּי לְאָבוּנָא וּמִדִּי לְאָבוּנָא קְנָא יָת כָּל נִכְסַיָּא הָדֵין:
@93 וַחֲזָא יַעֲקֹב יָת סְבַר אַפֵּי לָבָן וְהָא לֵיתוֹהִי עִמֵּהּ כְּמֵאִתְמַלִּי וּמִדְּקַמּוֹהִי:
@94 וַאֲמַר יְיָ לְיַעֲקֹב תּוּב לְאַרְעָא דַּאֲבָהָתָךְ וּלְיַלָּדֻתָךְ וִיהֵי מֵימְרִי בְּסַעְדָּךְ:
@95 וּשְׁלַח יַעֲקֹב וּקְרָא לְרָחֵל וּלְלֵאָה לְחַקְלָא לְוַת עָנֵהּ:
@96 וַאֲמַר לְהֵן חָזֵי אֲנָא יָת סְבַר אַפֵּי אֲבוּכֶן אֲרֵי לֵיתוֹהִי עִמִּי כְּמֵאִתְמַלִּי וּמִדְּקַמֹּהִי וֵאלָהֵהּ דְּאַבָּא הֲוָה בְּסַעְדִּי:
@97 וְאַתִּין יְדַעְתִּין אֲרֵי בְּכָל חֵילִי פְּלָחִית יָת אֲבוּכֶן:
@98 וַאֲבוּכֶן שְׁקַּר בִּי וְאַשְׁנִי יָת אַגְרִי עֲשַׂר זִמְנִין וְלָא שָׁבְקֵהּ יְיָ לְאַבְאָשָׁא עִמִּי:
@99 אִם כְּדֵין הֲוָה אֲמַר נְמוֹרִין יְהֵא אַגְרָךְ וִילִידָן כָּל עָנָא נְמוֹרִין וְאִם כְּדֵין הֲוָה אֲמַר רְגוֹלִין יְהֵא אַגְרָךְ וִילִידָן כָּל עָנָא רְגוֹלִין:
@100 וְאַפְרֵשׁ יְיָ יָת גֵּיתֵי דַּאֲבוּכוֹן וִיהַב לִי:
@101 וַהֲוָה בְּעִדַּן דְּאִתְיַחֲמָא עָנָא וּזְקָפִית עַיְנַי וַחֲזֵית בְּחֶלְמָא וְהָא תְיָשַׁיָּא דְּסָלְקִין עַל עָנָא רְגוֹלִין נְמוֹרִין וּפַצִיחִין:
@102 וַאֲמַר לִי מַלְאָכָא דַּיְיָ בְּחֶלְמָא יַעֲקֹב וַאֲמָרִית הָא אֲנָא:
@103 וַאֲמַר זְקוֹף כְּעַן עַינָיךְ וַחֲזֵי כָּל תְּיָשַׁיָּא דְּסָלְקִין עַל עָנָא רְגוֹלִין נְמוֹרִין וּפַצִיחִין אֲרֵי גְלֵי קֳדָמַי יָת כָּל דִּי לָבָן עָבֵד לָךְ:
@104 אֲנָא אֱלָהָא דְּאִתְגְּלֵיתִי עֲלָךְ בְּבֵית אֵל דִּי מְשַׁחְתָּא תַמָּן קָמָא דִּי קַיִּמְתָּא קֳדָמַי תַּמָּן קְיָם כְּעַן קוּם פּוּק מִן אַרְעָא הָדָא וְתוּב לְאַרְעָא יַלָּדוּתָךְ:
@105 וַאֲתִיבַת רָחֵל וְלֵאָה וַאֲמָרַן לֵהּ הַעוֹד (כְּעַן) לָנָא חֳלָק וְאַחֲסָנָא בְּבֵית אֲבוּנָא:
@106 הֲלָא נוּכְרָאָן אִתְחֲשַׁבְנָא לֵהּ אֲרֵי זַבְּנָנָא וַאֲכַל אַף מֵיכַל יָת כַּסְפָּנָא:
@107 אֲרֵי כָל עוּתְרָא דִּי אַפְרֵשׁ יְיָ מֵאֲבוּנָא דִּילָנָא הוּא וְדִבְּנָנָא וּכְעַן כֹּל דִּי אֲמַר יְיָ לָךְ עִבֵד:
@108 וְקָם יַעֲקֹב וּנְטַל יָת בְּנוֹהִי וְיָת נְשׁוֹהִי עַל גַּמְלַיָּא:
@109 וּדְבַר יָת כָּל גֵּיתוֹהִי וְיָת כָּל קִנְיָנֵהּ דִּקְנָא גֵּיתֵי קִנְיָנֵהּ דִּי קְנָא בְּפַדַּן אֲרָם לְמֵיתֵי לְוַת יִצְחָק אֲבוּהִי לְאַרְעָא כְנָעַן:
@110 וְלָבָן אֲזַל לְמִגַּז יָת עָנֵהּ וּנְסִּבַת רָחֵל יָת צַלְמָנַיָּא דִּי לַאֲבוּהָא:
@111 וְכַסִּי יַעֲקֹב מִן לִבָּא דְלָבָן אֲרַמָּאָה עַל דְּלָא חַוִּי לֵהּ אֲרֵי אָזֵל הוּא:
@112 וַאֲזַלּ הוּא וְכָל דִּי לֵהּ וְקָם וַעֲבַר יָת פְּרָת וְשַׁוִּי יָת אַפּוֹהִי לְטוּרָא דְגִלְעָד:
@113 וְאִתְחַוָא לְלָבָן בְּיוֹמָא תְלִיתָאָה אֲרֵי אֲזַל יַעֲקֹב:
@114 וּדְבַר יָת אַחוּהִי עִמֵּהּ וּרְדַף בַּתְרוֹהִי מַהֲלַךְ שִׁבְעַת יוֹמִין וְאַדְבֵּק יָתֵהּ בְּטוּרָא דְגִלְעָד:
@115 וַאֲתָא מֵימָר מִן קֳדָם יְיָ לְוַת לָבָן אֲרַמָּאָה בְּחֵילְמָא דְּלֵילְיָא וַאֲמַר לֵהּ אִסְתַּמַּר לָךְ דִּילְמָא תְמַלֵּיל עִם יַעֲקֹב מִטַּב עַד בִּישׁ:
@116 וְאַדְבֵּיק לָבָן יָת יַעֲקֹב וְיַעֲקֹב פְּרַס יָת מַשְׁכְּנֵהּ בְּטוּרָא וְלָבָן אַשְׁרֵי יָת אֲחוֹהִי בְּטוּרָא דְגִלְעָד:
@117 וַאֲמַר לָבָן לְיַעֲקֹב מָה עֲבַדְתָּ וְכַסֵּיתָא מִנִּי וּדְבַרְתָּא יָת בְּנָתַי כְּשַׁבְיוֹת חַרְבָּא:
@118 לְמָה אִטְמַרְתָּ לְמֵיזַל וְכַסֵּיתָא מִנִּי וְלָא חַוֵּיתָא לִי וְשַׁלָּחִתָּךְ פּוֹן בְּחֶדְוָא וּבְתוּשְׁבְּחָן בְּתוּפִּין וּבְכִנָּרִין:
@119 וְלָא שְׁבַקְתַּנִּי לְנַשָּׁקָא לִבְנַי וְלִבְנָתָי כְּעַן אַסְכֶּלְתָּא לְמֶעְבָּד:
@120 אִית חֵילָא בִידִי לְמֶעְבַּד עִמְּכוֹן בִּישׁ וֵאלָהָא דַּאֲבוּכוֹן בְּרַמְשָׁא אֲמַר לִי לְמֵימַר אִסְתַּמַּר לָּךְ מִלְּמַלָּלָא עִם יַעֲקֹב מִטַּב עַד בִּישׁ:
@121 וּכְעַן מֵיזַל אֲזַלְתָּ אֲרֵי חַמָּדָא חַמֵדְתָּא לְבֵית אָבוּךְ לְמָה נְסִבְתָּא יָת דַּחַלְתִּי:
@122 וַאֲתֵיב יַעֲקֹב וַאֲמַר לְלָבָן אֲרֵי דְחֵילִית אֲרֵי אֲמָרִית דִּילְמָא תָנֵיס יָת בְּנָתָךְ מִנִּי:
@123 עִם (נ''י אֲתַר) דִּי תַשְׁכַּח יָת דַּחַלְתָּךְ לָא יִתְקַיַּם קֳדָם אֲחָנָא אִשְׁתְּמוֹדַע לָךְ מָה דְעִמִּי וְסַב לָךְ וְלָא יְדַע יַעֲקֹב אֲרֵי רָחֵל נְסִיבָתְהוֹן:
@124 וְעַל לָבָן בְּמַשְׁכְּנָא דְיַעֲקֹב וּבְמַשְׁכְּנָא דְלֵאָה וּבְמַשְׁכְּנָא דְּתַרְתֵּין לְחֵינָתָא וְלָא אַשְׁכַּח וּנְפַק מִמַּשְׁכְּנָא דְלֵאָה וְעַל בְּמַשְׁכְּנָא דְרָחֵל:
@125 וְרָחֵל נְסִיבַת יָת צַלְמָנַיָּא וְשַׁוִּתִּנּוּן בַּעֲבִיטָא דְגַמְלָא וִיתִיבַת עֲלֵיהוֹן וּמַשִּׁישׁ לָבָן יָת כָּל מַשְׁכְּנָא וְלָא אַשְׁכָּח:
@126 וַאֲמֶרֶת לַאֲבוּהָא לָא יִתְקֵף בְּעֵינֵי רִבּוֹנִי אֲרֵי לָא אִכּוּל לְמֵיקַם מִן קֳדָמָךְ אֲרֵי אֹרַח נְשִׁין לִי וּבְלַשׁ וְלָא אַשְׁכַּח יָת צַלְמָנַיָּא:
@127 וּתְקֵיף לְיַעֲקֹב וּנְצָא עִם לָבָן וַאֲתֵיב יַעֲקֹב וַאֲמַר לְלָבָן מַה חוֹבִי מַה סוּרְחָנִי אֲרֵי רְדַפְתָּא בַּתְרָי:
@128 אֲרֵי מַשִּׁשְׁתָּא יָת כָּל מָנַי מָה אַשְׁכַּחְתָּא מִכֹּל מָנֵי בֵיתָךְ שַׁוִּי הָכָא קֳדָם אַחַי וְאַחָיךְ וְיוֹכִיחוּן בֵּין תַּרְוָנָא:
@129 דְּנַן עֶסְרִין שְׁנִין אֲנָא עִמָּךְ רְחֵלָיךְ וְעִזָּיךְ לָא אַתְכִּילוּ וְדִכְרֵי עָנָךְ לָא אֲכָלִית:
@130 דִּתְבִירָא לָא אַיְתֵיתִי לְוָתָךְ דַּהֲוַת שָׁגְיָא מִמִּנְיָנָא מִנִּי אַתְּ בָּעֵי לַהּ נְטָרִית בִּימָמָא וּנְטָּרִית בְּלֵילְיָא:
@131 הֲוֵיתִי בִימָמָא אֲכַלְנִי שַׁרְבָא וּגְלִידָא (הֲוָה) נָחֵית עֲלַי בְּלֵילְיָא וּנְדַד שִׁנְתִּי מֵעֵינָי:
@132 דְּנַן לִי עֶשְׂרִין שְׁנִין בְּבֵיתָךְ פְּלָחִתָּךְ אַרְבַּע עֶשְׂרֵי שְׁנִין בְּתַרְתֵּין בְּנָתָךְ וְשִׁתְּ שְׁנִין בְּעָנָךְ וְאַשְׁנֵיתָא יָת אַגְרִי עֲשַׂר זִמְנִין:
@133 אִילוּלָא פוֹן אֱלָהֵהּ דְּאַבָּא אֱלָהֵהּ דְּאַבְרָהָם וּדְדָחִיל לֵהּ יִצְחָק הֲוָה בְּסַעְדִּי אֲרֵי כְעַן רֵיקָן שִׁלַּחְתָּנִי יָת עַמְלִי וְיָת לֵיאוּת יְדַי גְלֵי קֳדָם יְיָ וְאוֹכַח בְּרַמְשָׁא:
@134 וַאֲתֵיב לָבָן וַאֲמַר לְיַעֲקֹב בְּנָתָא בְּנָתַי וּבְנַיָּא בְנַי וְעָנָא עָנִי וְכֹל דִּי אַתְּ חָזֵי דִּילִי הוּא וְלִבְנָתַי מָה אֶעְבֵּיד לְאִלֵּין יוֹמָא דֵין אוֹ לִבְנֵיהֶן דִּילִידָן:
@135 וּכְעַן אֱתָא נִגְזַר קְיָם אֲנָא וְאָתְּ וִיהֵי לְסָהִיד בֵּינִי וּבֵינָךְ:
@136 וּנְסִיב יַעֲקֹב אַבְנָא וּזְקָפַהּ קָמָא:
@137 וַאֲמַר יַעֲקֹב לַאֲחוֹהִי לְקוּטוּ אַבְנִין וּנְסִיבוּ אַבְנִין וַעֲבָדוּ דְּגוֹרָא וַאֲכָלוּ תַמָּן עַל דְּגוֹרָא:
@138 וּקְרָא לֵהּ לָבָן יְגַר שָׂהֲדוּתָא וְיַעֲקֹב קְרָא לֵהּ גַּלְעֵד:
@139 וַאֲמַר לָבָן דְּגוֹרָא הָדֵין סָהִיד בֵּינִי וּבֵינָךְ יוֹמָא דֵּין עַל כֵּן קְרָא שְׁמֵהּ גַּלְעֵד:
@140 וְסָכוּתָא דִּי אֲמַר יִסֶּךְ מֵימְרָא דַּיְיָ בֵּינִי וּבֵינָךְ אֲרֵי נִתכַּסִּי גּבַר מֵחַבְרֵהּ:
@141 אִם תְּעַנֵּי יָת בְּנָתַי וְאִם תִּסַּב נְשִׁין עַל בְּנָתַי לֵית אֱנַשׁ עִמָּנָא חָזֵי מֵימְרָא דַּיְיָ סָהִיד בֵּינִי וּבֵינָךְ:
@142 וַאֲמַר לָבָן לְיַעֲקֹב הָא דְּגוֹרָא הָדֵין וְהָא קַמְתָא דִּי אֲקֵימִית בֵּינִי וּבֵינָךְ:
@143 סָהִיד דְּגוֹרָא הָדֵין וְסָהֲדָא קָמָא אִם אֲנָא לָא אֶעְבַּר לְוָתָךְ יָת דְּגוֹרָא הָדֵין וְאִם אַתְּ לָא תֵעִבַּר לְוָתִי יָת דְּגוֹרָא הָדֵין וְיָת קַמְתָא הָדָא לְבִישׁוּ:
@144 אֱלָהֵהּ דְּאַבְרָהָם וֵאֱלָהֵהּ דְּנָחוֹר יְדוּנוּן בֵּינָנָא אֱלָהֵהּ דַּאֲבוּהוֹן וְקַיֵּים יַעֲקֹב בִּדְדָחִיל לֵהּ אֲבוּהִי יִצְחָק:
@145 וּנְכֵס יַעֲקֹב נִכְסָתָא בְּטּוּרָא וּקְרָא לַאֲחוֹהִי לְמֵיכַל לַחְמָא וַאֲכָלוּ לַחְמָא וּבִיתוּ בְּטוּרָא:
@146 וְאַקְדֵּם לָבָן בְּצַפְרָא וּנְשַׁק לִבְנוֹהִי וְלִבְנָתֵהּ וּבָרִיךְ יָתְהֵן וַאֲזַל וְתַב לָבָן לְאַתְרֵהּ:
@147 וְיַעֲקֹב אֲזָל לְאָרְחֵהּ וַעֲרָעוּ בֵהּ מַלְאָכַיָּא דַּיְיָ:
@148 וַאֲמַר יַעֲקֹב כַּד חֲזָנוּן מַשְׁרִיתָא מִן קֳדָם יְיָ דֵּין וּקְרָא שְׁמָא דְאַתְרָא הַהוּא מַחֲנָיִם: פפפ:

@1 **ויצא יעקב.** על ידי שבשביל שרעות בנות כנען בעיני יצחק אביו הלך עשו אל ישמעאל, הפסיק הענין בפרשתו של יעקב וכתב (לעיל כח ו) וירא עשו כי ברך וגו' , ומשגמר חזר לענין הראשון: **ויצא יעקב מבאר שבע.** לא היה צריך לכתוב אלא וילך יעקב חרנה, ולמה הזכיר יציאתו, אלא מגיד שיציאת צדיק מן המקום עושה רושם, שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה פנה זיוה פנה הדרה וכן (רות א ז) ותצא מן המקום, האמור בנעמי ורות: **וילך חרנה.** יצא ללכת לחרן:
@2 **ויפגע במקום.** לא הזכיר הכתוב באיזה מקום אלא במקום הנזכר במקום אחר, הוא הר המוריה שנאמר בו (לעיל כב ד) וירא את המקום מרחוק: **ויפגע.** כמו (יהושע טז ז) ופגע ביריחו, (שם יט יא) ופגע בדבשת. ורבותינו פרשו לשון תפלה כמו (ירמיה ז טז) ואל תפגע בי, ולמדנו שתקן תפלת ערבית. ושנה הכתוב ולא כתב ויתפלל, ללמדך שקפצה לו הארץ, כמו שמפורש בפרק גיד הנשה (חלין צא ב) : **כי בא השמש.** היה לו לכתוב ויבא השמש. כי בא השמש, משמע ששקעה לו חמה פתאם שלא בעונתה כדי שילין שם: **וישם מראשותיו.** עשאן כמין מרזב סביב לראשו שהיה ירא מפני חיות רעות. התחילו מריבות זו עם זו, זאת אומרת עלי יניח צדיק את ראשו, וזאת אומרת עלי יניח, מיד עשאן הקדוש ברוך הוא אבן אחת, וזהו שנאמר (פסוק יח) ויקח את האבן אשר שם מראשותיו: **וישכב במקום ההוא.** לשון מעוט באותו מקום שכב, אבל ארבע עשרה שנים ששמש בבית עבר לא שכב בלילה, שהיה עוסק בתורה:
@3 **עולים ויורדים.** עולים תחלה ואחר כך יורדים, מלאכים שלווהו בארץ אין יוצאים חוצה לארץ ועלו לרקיע, וירדו מלאכי חוצה לארץ ללוותו:
@4 **נצב עליו.** לשמרו: **ואלהי יצחק.** אף על פי שלא מצינו במקרא שיחד הקדוש ברוך הוא שמו על הצדיקים בחייהם לכתוב אלהי פלוני, משום שנאמר (איוב טו טו) הן בקדושיו לא יאמין, כאן ייחד שמו על יצחק לפי שכהו עיניו וכלוא היה בבית, והרי הוא כמת, ויצר הרע פסק ממנו: **שכב עליה.** קפל הקדוש ברוך הוא כל ארץ ישראל תחתיו, רמז לו שתהא נחה לכבש לבניו:
@5 **ופרצת.** וחזקת, כמו (שמות א יב) וכן יפרוץ:
@6 **אנכי עמך.** לפי שהיה ירא מעשו ומלבן: **עד אשר אם עשיתי.** אם משמש בלשון כי: **דברתי לך.** לצרכך ועליך, מה שהבטחתי לאברהם על זרעו, לך הבטחתיו ולא לעשו, שלא אמרתי לו כי יצחק יקרא לך זרע, אלא כי ביצחק, ולא כל. יצחק וכן כל לי ולך ולו ולהם הסמוכים אצל דבור, משמשים לשון על, וזה, יוכיח שהרי עם יעקב לא דבר קדם לכן:
@7 **ואנכי לא ידעתי.** שאלו ידעתי לא ישנתי במקום קדוש כזה:
@8 **כי אם בית אלהים.** אמר רבי אלעזר בשם רבי יוסי בן זמרא הסלם הזה עומד בבאר שבע ואמצע שפועו מגיע כנגד בית המקדש, שבאר שבע עומד בדרומה של יהודה, וירושלים בצפונה בגבול שבין יהודה ובנימין, ובית אל היה בצפון של נחלת בנימין בגבול שבין בנימין ובין בני יוסף, נמצא סלם שרגליו בבאר שבע וראשו בבית אל מגיע אמצע שפועו נגד ירושלים. וכלפי שאמרו רבותינו שאמר הקדוש ברוך הוא צדיק זה בא לבית מלוני ויפטר בלא לינה, ועוד אמרו יעקב קראה לירושלים בית אל וזו לוז היא ולא ירושלים ומהיכן למדו לומר כן. אומר אני שנעקר הר המוריה ובא לכאן, וזהו היא קפיצת הארץ האמורה בשחיטת חלין (חולין צא ב) , שבא בית המקדש לקראתו עד בית אל, וזהו ויפגע במקום. [ואם תאמר וכשעבר יעקב על בית המקדש מדוע לא עכבו שם, איהו לא יהב לביה להתפלל במקום שהתפללו אבותיו, ומן השמים יעכבוהו, איהו עד חרן אזל כדאמרינן בפרק גיד הנשה (חולין צא ב) , וקרא מוכיח וילך חרנה, כי מטא לחרן אמר אפשר שעברתי על מקום שהתפללו אבותי ולא התפללתי בו, יהב דעתיה למהדר וחזר עד בית אל וקפצה לו הארץ]: **מה נורא.** תרגום מה דחילו אתרא הדין. דחילו שם דבר הוא, כמו סוכלתנו, וכסו למלבש: **וזה שער השמים.** מקום תפלה לעלות תפלתם השמימה. ומדרשו שבית המקדש של מעלה מכון כנגד בית המקדש של מטה כ **אם יהיה אלהים עמדי.** אם ישמור לי הבטחות הללו שהבטיחני להיות עמדי, כמו שאמר לי (פסוק טו) והנה אנכי עמך: **ושמרני.** כמו שאמר לי (פסוק טו) ושמרתיך בכל אשר תלך: **ונתן לי לחם לאכול.** כמו שאמר (פסוק טו) כי לא אעזבך, והמבקש לחם הוא קרוי נעזב, שנאמר (תהלים לז כה) ולא ראיתי צדיק נעזב וזרעו מבקש לחם:
@12 **ושבתי.** כמו שאמר לי (פסוק טו) והשיבותיך אל האדמה: **בשלום.** שלם מן החטא, שלא אלמד מדרכי לבן: **והיה ה' לי לאלהים.** שיחול שמו עלי מתחלה ועד סוף, שלא ימצא פסול בזרעי, כמו שנאמר (פסוק טו) אשר דברתי לך, והבטחה זו הבטיח לאברהם, שנאמר (שם יז ז) להיות לך לאלהים ולזרעך אחריך:
@13 **והאבן הזאת.** כך תפרש וי''ו זו של והאבן, אם תעשה לי את אלה, אף אני אעשה זאת: **והאבן הזאת אשר שמתי מצבה** וגו' **.** כתרגומו אהי פלח עלה קדם ה' וכן עשה בשובו מפדן ארם, כשאמר לו (לקמן לה א) קום עלה בית אל, מה נאמר שם (שם יד) ויצב יעקב מצבה וגו' ויסך עליה נסך:
@14 **וישא יעקב רגליו.** משנתבשר בשורה טובה שהובטח בשמירה, נשא לבו את רגליו ונעשה קל ללכת. כך מפרש בבראשית רבה (ע ח) :
@15 **ישקו העדרים.** משקים הרועים את העדרים, והמקרא דבר בלשון קצרה:
@16 **ונאספו.** רגילים היו להאסף לפי שהיתה האבן גדולה: **וגללו.** וגוללין ותרגומו ומגנדרין, כל לשון הוה משתנה לדבר בלשון עתיד ובלשון עבר לפי שכל דבר ההוה תמיד כבר היה ועתיד להיות: **והשיבו.** תרגומו ומתיבין:
@19 **באה עם הצאן.** הטעם באל''ף, ותרגומו אתיא. (פסוק ט) ורחל באה, הטעם למעלה בבי''ת ותרגומו אתת. הראשון לשון עושה, והשני לשון עשתה:
@20 **הן עוד היום גדול.** לפי שראה אותם רובצים, כסבור שרוצים לאסוף המקנה הביתה ולא ירעו עוד, אמר להם הן עוד היום גדול, כלומר אם שכירים אתם לא שלמתם פעלת היום, ואם הבהמות שלכם אף על פי כן לא עת האסף המקנה וגו' :
@21 **לא נוכל.** להשקות, לפי שהאבן גדולה: **וגללו.** זה מתורגם ויגנדרון, לפי שהוא לשון עתיד:
@23 **ויגש יעקב ויגל.** כזה שמעביר את הפקק מעל פי צלוחית, להודיעך שכחו גדול:
@24 **ויבך.** לפי שצפה ברוח הקודש שאינה נכנסת עמו לקבורה. דבר אחר לפי שבא בידים ריקניות, אמר אליעזר עבד אבי אבא היו בידיו נזמים וצמידים ומגדנות, ואני אין בידי כלום. לפי שרדף אליפז בן עשו במצות אביו אחריו להרגו והשיגו, ולפי שגדל אליפז בחיקו של יצחק משך ידו. אמר לו מה אעשה לצווי של אבא, אמר לו יעקב טול מה שבידי, והעני חשוב כמת:
@25 **כי אחי אביה הוא.** קרוב לאביה, כמו (לעיל יג ח) אנשים אחים אנחנו. ומדרשו אם לרמאות הוא בא גם אני אחיו ברמאות, ואם אדם כשר הוא, גם אני בן רבקה אחותו הכשרה: **ותגד לאביה.** לפי שאמה מתה לא היה לה להגיד אלא לו:
@26 **וירץ לקראתו.** כסבור ממון הוא טעון, שהרי עבד הבית בא לכאן בעשרה גמלים טעונים: **ויחבק.** כשלא ראה עמו כלום אמר שמא זהובים הביא והנם בחיקו: **וינשק לו.** אמר שמא מרגליות הביא והם בפיו: **ויספר ללבן.** שלא בא אלא מתוך אונס אחיו, ושנטלו ממונו ממנו:
@27 **אך עצמי ובשרי.** מעתה אין לי לאספך הביתה הואיל ואין בידך כלום, אלא מפני קורבה אטפל בך חדש ימים, וכן עשה ואף זו לא לחנם שהיה רועה צאנו:
@28 **הכי אחי אתה.** לשון תמה, וכי בשביל שאחי אתה תעבדני חנם: **ועבדתני.** כמו ותעבדני, וכן כל תבה שהיא לשון עבר הוסיף וי''ו בראשה היא הופכת התבה להבא:
@30 **ועיני לאה רכות.** שהיתה סבורה לעלות בגורלו של עשו ובוכה שהיו הכל אומרים שני בנים לרבקה ושתי בנות ללבן, הגדולה לגדול והקטנה לקטן: **תאר.** הוא צורת הפרצוף לשון (ישעיה מד יג) יתארהו בשרד, קונפ''ס בלע''ז : **מראה.** הוא זיו קלסתר:
@31 **אעבדך שבע שנים.** הם ימים אחדים שאמרה לו אמו (לעיל כז מד) וישבת עמו ימים אחדים. ותדע שכן הוא, שהרי כתיב (להלן פסוק כ) ויהיו בעיניו כימים אחדים: **ברחל בתך הקטנה.** כל הסימנים הללו למה, לפי שיודע בו שהוא רמאי אמר לו אעבדך ברחל, ושמא תאמר רחל אחרת מן השוק, תלמוד לומר בתך, ושמא תאמר אחליף ללאה שמה ואקרא שמה רחל, תלמוד לומר הקטנה ואף על פי כן לא הועיל לו שהרי רמהו:
@34 **מלאו ימי.** שאמרה לי אמי. ועוד מלאו ימי, שהרי אני בן שמונים וארבע שנה ואימתי אעמיד שנים עשר שבטים, וזהו שאמר ואבואה אליה, והלא קל שבקלים אינו אומר כן, אלא להוליד תולדות אמר כן:
@38 **ויהי בבקר והנה היא לאה.** אבל בלילה לא היתה לאה, לפי שמסר יעקב לרחל סימנים, וכשראתה רחל שמכניסין לו לאה אמרה עכשיו תכלם אחותי, עמדה ומסרה לה אותן סימנים:
@40 **מלא שבוע זאת.** דבוק הוא שהרי נקוד בחטף שבוע של זאת, והן שבעת ימי המשתה בתלמוד ירושלמי במועד קטן (א ז) . ואי אפשר לומר שבוע ממש, שאם כן היה צריך לנקד בפתח השין. ועוד ששבוע לשון זכר, כדכתיב (דברים טז ט) שבעה שבעת תספר לך, לפיכך אין משמע שבוע אלא שבעה שייטיינ''א בלע''ז : **ונתנה לך.** לשון רבים, כמו (לעיל יא ז) נרדה ונבלה, (שם ג) ונשרפה, אף זה לשון ונתן **גם את זאת.** [מיד לאחר שבעת ימי המשתה] ותעבוד לאחר נשואיה:
@43 **ויעבוד עמו עוד שבע שנים אחרות.** הקישן לראשונות, מה ראשונות באמונה אף האחרונות באמונה, ואף על פי שברמאות בא עליו:
@45 **ותקרא שמו ראובן.** רבותינו פרשו, אמרה ראו מה בין בני לבן חמי שמכר הבכורה ליעקב, וזה לא מכרה ליוסף ולא ערער עליו, ולא עוד שלא ערער עליו אלא שבקש להוציאו מן הבור:
@47 **הפעם ילוה אישי.** לפי שהאמהות נביאות היו ויודעות ששנים עשר שבטים יוצאים מיעקב וארבע נשים ישא, אמרה מעתה אין לו פתחון פה עלי, שהרי נטלתי כל חלקי בבנים: **על כן.** כל מי שנאמר בו על כן מרבה באוכלוסין, חוץ מלוי שהארון היה מכלה בהם: **קרא שמו לוי.** תמהתי שבכלם כתיב ותקרא, וזה כתב בו קרא, ויש מדרש אגדה באלה הדברים רבה ששלח הקדוש ברוך הוא גבריאל והביאו לפניו וקרא לו שם זה ונתן לו עשרים וארבע מתנות כהנה, ועל שם שלוהו במתנות קראו לוי:
@48 **הפעם אודה.** שנטלתי יותר מחלקי, מעתה יש לי להודות:
@49 **ותקנא רחל באחותה.** קנאה במעשיה הטובים, אמרה אלולי שצדקה ממני לא זכתה לבנים: **הבה לי.** וכי כך עשה אביך לאמך, והלא התפלל עליה: **מתה אנכי.** מכאן למי שאין לו בנים שחשוב כמת:
@50 **התחת אלהים אנכי.** וכי במקומו אני: **אשר מנע ממך.** את אמרת שאעשה כאבא, אני איני כאבא, אבא לא היו לו בנים אני יש לי בנים, ממך מנע ולא ממני:
@51 **על ברכי.** כתרגומו ואנא ארבי: **ואבנה גם אנכי.** מהו גם, אמרה לו זקנך אברהם היו לו בנים מהגר, וחגר מתניו כנגד שרה, אמר לה זקנתי הכניסה צרתה לביתה, אמרה לו אם הדבר הזה מעכב, הנה אמתי בלהה, ואבנה גם אנכי ממנה כשרה:
@54 **דנני אלהים.** דנני וחיבני וזכני:
@56 **נפתולי אלהים.** מנחם בן סרוק פרשו במחברת (במדבר יט טו) צמיד פתיל, חבורים, מאת המקום נתחברתי עם אחותי לזכות לבנים. ואני מפרשו לשון (דברים לב ה) עקש ופתלתול, נתעקשתי והפצרתי פצירות ונפתולים הרבה למקום להיות שוה לאחותי: **גם יכלתי.** הסכים על ידי. ואונקלוס תרגם לשון תפלה, כמו נפתולי אלהים, נתפללתי בקשות החביבות לפניו, נתקבלתי ונעתרתי כאחותי: **נפתלתי.** נתקבלה תפלתי. ומדרש אגדה יש רבים בלשון נוטריקון:
@58 **ותלד זלפה.** בכלן נאמר הריון חוץ מזלפה לפי שהיתה בחורה מכולן ותינוקת בשנים ואין הריון נכר בה, וכדי לרמות ליעקב נתנה לבן ללאה שלא יבין שמכניסין לו את לאה, שכך מנהג לתן שפחה גדולה לגדולה וקטנה לקטנה:
@59 **בא גד.** בא מזל טוב, כמו (שבת סז ב) גד גדי וסנוק לא, ודומה לו (ישעיה סה יא) העורכים לגד שלחן. ומדרש אגדה שנלד מהול, כמו (דניאל ד כ) גדו אילנא, ולא ידעתי על מה נכתבה תבה אחת. דבר אחר למה נקראת תיבה אחת בגד, כמו בגדת בי כשבאת אל שפחתי, כאיש שבגד באשת נעורים:
@62 **בימי קציר חטים.** להגיד שבחן של שבטים, שעת הקציר היה ולא פשט ידו בגזל להביא חטים ושעורים אלא דבר ההפקר שאין אדם מקפיד בו: **דודאים.** סיגלי, עשב הוא ובלשון ישמעאל יסמי''ן:
@63 **ולקחת גם את דודאי בני.** בתמיהה, ולעשות עוד זאת לקח גם את דודאי בני ותרגומו ולמסב: **לכן ישכב עמך הלילה.** שלי היתה שכיבת לילה זו ואני נותנה לך תחת דודאי בנך. ולפי שזלזלה במשכב הצדיק לא זכתה להקבר עמו:
@64 **שכר שכרתיך.** נתתי לרחל שכרה: **בלילה הוא.** הקדוש ברוך הוא סיע שיצא משם יששכר:
@65 **וישמע אלהים אל לאה.** שהיתה מתאוה ומחזרת להרבות שבטים:
@68 **זבד טוב.** כתרגומו: **יזבלני.** לשון (מלכים א' ח יג) בית זבול הירבירייריא''ה בלע''ז בית מדור. מעתה לא תהא עיקר דירתו אלא עמי שיש לי בנים כנגד כל נשיו:
@69 **דינה.** פרשו רבותינו שדנה לאה דין בעצמה אם זה זכר לא תהא רחל אחותי כאחת השפחות, והתפללה עליו ונהפך לנקבה:
@70 **ויזכר אלהים את רחל.** זכר לה שמסרה סימניה לאחותה, ושהיתה מצרה שלא תעלה בגורלו של עשו שמא יגרשנה יעקב לפי שאין לה בנים, ואף עשו הרשע כך עלה בלבו כששמע שאין לה בנים. הוא שיסד הפיט (קרובות דר''ה שחרית) האדמון כבט שלא חלה, צבה לקחתה לו ונתבהלה:
@71 **אסף.** הכניסה במקום שלא תראה וכן (ישעיה ד א) אסף חרפתנו, (שמות ט יט) ולא יאסף הביתה, (יואל ד טו) אספו נגהם, (ישעיה ס כ) וירחך לא יאסף, לא יטמן: **חרפתי.** שהייתי לחרפה שאני עקרה, והיו אומרים עלי שאעלה לחלקו של עשו הרשע. ומדרש אגדה כל זמן שאין לאשה בן אין לה במי לתלות סרחונה, משיש לה בן תולה בו. מי שבר כלי זה, בנך, מי אכל תאנים אלו, בנך:
@72 **יוסף ה' לי בן אחר.** יודעת היתה בנבואה שאין יעקב עתיד להעמיד אלא שנים עשר שבטים, אמרה יהי רצון שאותו שהוא עתיד להעמיד יהא ממני, לכך לא נתפללה אלא על בן אחר:
@73 **כאשר ילדה רחל את יוסף.** משנלד שטנו של עשו, שנאמר (עובדיה א יח) והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש, אש בלא להבה אינו שולט למרחוק, משנלד יוסף בטח יעקב בהקדוש ברוך הוא ורצה לשוב:
@74 **תנה את נשי** וגו' **.** איני רוצה לצאת כי אם ברשות:
@75 **נחשתי.** מנחש היה, נסיתי בנחוש שלי שעל ידך באה לי ברכה, כשבאת לכאן לא היו לי בנים, שנאמר (לעיל כט ו) והנה רחל בתו באה עם הצאן, אפשר יש לו בנים והוא שולח בתו אצל הרועים, ועכשיו היו לו בנים שנאמר (להלן לא א) וישמע את דברי בני לבן:
@76 **נקבה שכרך.** כתרגומו פריש אגרך:
@77 **ואת אשר היה מקנך אתי.** את חשבון מעוט מקנך שבא לידי מתחלה כמה היו:
@78 **לרגלי.** עם רגלי, בשביל ביאת רגלי באת אצלך הברכה, כמו (שמות יא ח) העם אשר ברגלך, (שופטים ח ה) לעם אשר ברגלי, הבאים עמי: **גם אנכי לביתי.** לצורך ביתי, עכשיו אין עושין לצרכי אלא בני וצריך אני להיות עושה גם אני עמהם לסמכן, וזהו גם:
@80 **נקד.** מנמר בחברבורות דקות, כמו נקדות, פוינטור''א בלע''ז : **טלוא.** לשון טלאים חברבורות רחבות: **חום.** שחום דומה לאדום, רו''ש בלע''ז [אדום] לשון משנה שחמתית ונמצאת לבנה, לענין התבואה: **והיה שכרי.** אותן שיולדו מכאן ולהבא נקדים וטלואים בעזים ושחומים בכשבים יהיו שלי ואותן שישנן עכשיו הפרש מהם והפקידם ביד בניך, שלא תאמר לי על הנלדים מעתה אלו היו שם מתחלה, ועוד שלא תאמר לי על ידי הזכרים שהן נקדים וטלואים תלדנה הנקבות דוגמתן מכאן ואלך:
@81 **וענתה בי** וגו' **.** אם תחשדני שאני נוטל משלך כלום, תענה בי צדקתי, כי תבא צדקתי ותעיד על שכרי לפניך, שלא תמצא בעדרי כי אם נקדים וטלואים, וכל שתמצא בהן שאינו נקוד או טלוא או חום בידוע שגנבתיו לך, ובגנבה הוא שרוי אצלי:
@82 **הן.** לשון הן, קבלת דברים: **לו יהי כדברך.** הלואי שתחפץ בכך:
@83 **ויסר.** לבן ביום ההוא וגו' : **התישים.** עזים זכרים: **כל אשר לבן בו.** כל אשר היתה בו חברבורית לבנה: **ויתן.** לבן ביד בניו:
@84 **הנותרת.** הרעועות שבהן החולות והעקרות, שאינן אלא שירים, אותן מסר לו:
@85 **מקל לבנה.** עץ הוא ושמו לבנה, כמה דתימא (הושע ד יג) תחת אלון ולבנה, ואומר אני הוא שקורין טרינבל''א בלע''ז שהוא לבן [צפצפה עצנית]: **לח.** כשהוא רטוב: **ולוז.** ועוד לקח מקל לוז, עץ שגדלין בו אגוזים דקים קולדר''א בלע''ז [אלסר]: **וערמון.** קשטיניי''ר בלע''ז [עץ ערמון]: **פצלות.** קלופים קלופים, שהיה עושהו מנמר: **מחשף הלבן.** גלוי לובן של מקל. כשהיה קולפו היה נראה ונגלה לובן שלו במקום הקלוף:
@86 **ויצג.** תרגומו ודעיץ, לשון תחיבה ונעיצה הוא בלשון ארמי, והרבה יש בתלמוד (שבת נ ב) דצה ושלפה, (חולין צג ב) דץ ביה מידי. דצה כמו דעצה, אלא שמקצר את לשונו: **ברהטים.** במרוצת המים, בבריכות העשויות בארץ, להשקות שם הצאן: **אשר תבאן** וגו' **ברהטים.** אשר תבאנה הצאן לשתות, שם הציג המקלות לנכח הצאן: **ויחמנה.** הבהמה רואה את המקלות והיא נרתעת לאחוריה, והזכר רובעה ויולדת כיוצא בו. ר' הושעיא אומר המים נעשין זרע במעיהן ולא היו צריכות לזכר, וזהו ויחמנה וגו' :
@87 **אל המקלות.** אל מראות המקלות: **עקדים.** משנים במקום עקידתן, הם קרסלי ידיהן ורגליהן:
@88 **והכשבים הפריד יעקב.** הנלדים עקדים נקדים הבדיל והפריד לעצמן ועשה אותן עדר עדר לבדו, והוליך אותו העדר העקוד לפני הצאן, ופני הצאן ההולכות אחריהם צופות אליהם, וזהו שנאמר ויתן פני הצאן אל עקוד, שהיו פני הצאן אל העקדים, ואל כל חום שמצא בצאן לבן: **וישת לו עדרים.** כמו שפרשתי:
@89 **המקשרות.** כתרגומו הבכירות ואין לו עד במקרא להוכיח עליו. ומנחם חברו עם (שמואל ב' טו לא) אחיתפל בקשרים, (שם טו י) ויהי הקשר אמיץ, אותן המתקשרות יחד למהר עבורן:
@90 **ובהעטיף.** לשון אחור, כתרגומו ובלקישות. ומנחם חברו עם (ישעיה ג כג) המחלצות והמעטפות, לשון עטיפת כסות, כלומר מתעטפות בעורן וצמרן ואינן מתאוות להתיחם על ידי הזכרים:
@91 **צאן רבות.** פרות ורבות יותר משאר צאן: **ושפחות ועבדים.** מוכר צאנו בדמים יקרים ולוקח לו כל אלה:
@92 **עשה.** כנס, כמו (ש''א יד מח) ויעש חיל ויך את עמלק:
@94 **שוב אל ארץ אבותיך.** ושם אהיה עמך, אבל בעודך מחבר לטמא אי אפשר להשרות שכינתי עליך:
@95 **ויקרא לרחל וללאה.** לרחל תחלה ואחר כך ללאה שהיא היתה עקרת הבית, שבשבילה נזדוג יעקב עם לבן, ואף בניה של לאה מודים בדבר, שהרי בעז ובית דינו משבט יהודה אומרים (רות ד יא) כרחל וכלאה אשר בנו שתיהם וגו' , הקדימו רחל ללאה:
@98 **עשרת מנים.** אין מונים פחות מעשרה: **מנים.** לשון סכום כלל החשבון, והן עשיריות, למדנו שהחליף תנאו מאה פעמים:
@101 **והנה העתודים.** אף על פי שהבדילם לבן כלם שלא יתעברו הצאן דוגמתן, היו המלאכים מביאין אותן מעדר המסור ביד בני לבן לעדר שביד יעקב: **וברדים.** כתרגומו ופציחין פיישי''ד בלע''ז [מנומש], חוט של לבן מקיף את גופו סביב, חברבורית שלו פתוחה ומפולשת מזן אל זן, ואין לי להביא עד מן המקרא:
@104 **האל בית אל.** כמו אל בית אל, הה''א יתרה, ודרך מקראות לדבר כן, כמו (במדבר לד ב) כי אתם באים אל הארץ כנען: **משחת שם.** לשון רבוי וגדלה כשנמשח למלכות, כך (לעיל כח יח) ויצק שמן על ראשה, להיות משוחה למזבח: **אשר נדרת לי.** וצריך אתה לשלמו, שאמרת (שם כב) יהיה בית אלהים, שתקריב שם קרבנות:
@105 **העוד לנו חלק.** למה נעכב על ידך מלשוב, כלום אנו מיחלות לירש בנכסי אבינו כלום בין הזכרים:
@106 **הלוא נכריות נחשבנו לו.** אפלו בשעה שדרך בני אדם לתת נדוניא לבנותיו בשעת נשואין, נהג עמנו כנכריות, כי מכרנו לך בשכר הפעלה: **את כספנו.** שעכב דמי שכר פעלתך:
@107 **כי כל העשר.** כי זה משמש בלשון אלא, כלומר משל אבינו אין לנו כלום אלא מה שהציל הקדוש ברוך הוא מאבינו שלנו הוא: **הציל.** לשון הפריש, וכן כל לשון הצלה שבמקרא לשון הפרשה, שמפרישו מן הרעה ומן האויב:
@108 **את בניו ואת נשיו.** הקדים זכרים לנקבות, ועשו הקדים נקבות לזכרים, שנאמר (לקמן לו ו) ויקח עשו את נשיו ואת בניו וגו' :
@109 **מקנה קנינו.** מה שקנה מצאנו עבדים ושפחות וגמלים וחמורים:
@110 **לגזז את צאנו.** שנתן ביד בניו דרך שלשת ימים בינו ובין יעקב: **ותגנב רחל את התרפים.** להפריש את אביה מעבודה זרה נתכונה:
@113 **ביום השלישי.** שהרי דרך שלשת ימים היה ביניהם:
@114 **את אחיו.** קרוביו: **דרך שבעת ימים.** כל אותן שלשה ימים שהלך המגיד להגיד ללבן הלך יעקב לדרכו. נמצא יעקב רחוק מלבן ששה ימים, ובשביעי השיגו לבן, למדנו שכל מה שהלך יעקב בשבעה ימים הלך לבן ביום אחד (שנאמר וירדוף אחריו דרך שבעת ימים, ולא נאמר וירדוף אחריו שבעת ימים) :
@115 **מטוב עד רע.** כל טובתן של רשעים רעה היא אצל הצדיקים:
@117 **כשביות חרב.** כל חיל הבא למלחמה קרוי חרב:
@118 **ותגנב אתי.** גנבת את דעתי:
@120 **יש לאל ידי.** יש כח וחיל בידי לעשות עמכם רע. וכל אל שהוא לשון קדש על שם עזוז ורוב אונים הוא:
@121 **נכספתה.** חמדת, והרבה יש במקרא (תהלים פד ג) נכספה וגם כלתה נפשי, (איוב יד טו) למעשה ידיך תכסף:
@122 **כי יראתי** וגו' **.** השיבו על ראשון ראשון, שאמר לו (פסוק כו) ותנהג את בנותי וגו' :
@123 **לא יחיה.** ומאותה קללה מתה רחל בדרך: **מה עמדי.** משלך:
@124 **באהל יעקב.** הוא אהל רחל, שהיה יעקב תדיר אצלה, וכן הוא אומר (להלן מו יט) בני רחל אשת יעקב, ובכלן לא נאמר אשת יעקב: **ויבא באהל רחל.** כשיצא מאהל לאה חזר לו לאהל רחל קודם שחפש באהל האמהות. וכל כך למה, לפי שהיה מכיר בה שהיא משמשנית:
@125 **בכר הגמל.** לשון כרים וכסתות כתרגומו בעביטא דגמלא, והיא מרדעת העשויה כמין כר ובעירובין (דף טז א) הקיפוה בעביטין, והן עביטי גמלים, בשטי''ל בלע''ז :
@127 **דלקת.** רדפת, כמו (איכה ד יט) על ההרים דלקנו, וכמו (ש''א יז נג) מדלק אחרי פלשתים:
@128 **ויוכיחו.** ויבררו עם מי הדין, אפרובי''ר בלע''ז :
@129 **לא שכלו.** לא הפילו עבורם, כמו (הושע ט יד) רחם משכיל, (איוב כא י) תפלט פרתו ולא תשכל: **ואילי צאנך.** מכאן אמרו איל בן יומו קרוי איל, שאם לא כן מה שבחו, אילים לא אכל אבל כבשים אכל, אם כן גזלן הוא:
@130 **טרפה.** על ידי ארי או זאב: **אנכי אחטנה.** לשון (שופטים כ טז) קולע באבן אל השערה ולא יחטא, (מ''א א כא) אני ובני שלמה חטאים, חסרים, אנכי אחסרנה, אם חסרה חסרה לי, שמידי תבקשנה: **אנכי אחטנה.** תרגומו דהות שגיא ממנינא שהיתה נפקדת ומחסרת, כמו (במדבר לא מט) ולא נפקד ממנו איש, תרגומו ולא שגא: **גנבתי יום וגנבתי לילה.** גנובת יום או גנובת לילה הכל שלמתי: **גנבתי.** כמו (איכה א א) רבתי בגוים שרתי במדינות, (ישעיה א כא) מלאתי משפט, (הושע י יא) אהבתי לדוש:
@131 **אכלני חרב.** לשון (דברים ד כד) אש אכלה: **וקרח.** כמו (תהלים קמז יז) משליך קרחו, תרגומו גלידא: **שנתי.** לשון שינה:
@132 **ותחלף את משכרתי.** היית משנה תנאי שבינינו מנקוד לטלוא ומעקדים לברדים:
@133 **ופחד יצחק.** לא רצה לומר אלהי יצחק, שאין הקדוש ברוך הוא מיחד שמו על הצדיקים בחייהם, ואף על פי שאמר לו בצאתו מבאר שבע (לעיל כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק, בשביל שכהו עיניו והרי הוא כמת, יעקב נתירא לומר אלהי ואמר ופחד: **ויוכח.** לשון תוכחה הוא ולא לשון הוכחה:
@134 **מה אעשה לאלה.** איך תעלה על לבי להרע להן:
@135 **והיה לעד.** הקדוש ברוך הוא:
@137 **לאחיו.** הם בניו, שהיו לו אחים נגשים אליו לצרה ולמלחמה:
@138 **יגר שהדותא.** תרגומו של גלעד: **גלעד.** כמו גלעד:
@140 **והמצפה אשר אמר** וגו' **.** והמצפה אשר בהר הגלעד, כמו שכתוב (שופטים יא כט) ויעבר את מצפה גלעד. ולמה נקרא שמה מצפה, לפי שאמר כל אחד מהם לחברו יצף ה' ביני ובינך אם תעבור את הברית: **כי נסתר.** ולא נראה איש את רעהו:
@141 **בנתי בנתי.** שתי פעמים, אף בלהה וזלפה בנותיו היו מפלגש: **אם תענה את בנתי.** למנוע מהם עונת תשמיש:
@142 **יריתי.** כמו (שמות טו ד) ירה בים, כזה שהוא יורה חנית:
@143 **אם אני.** הרי אם משמש בלשון אשר, כמו (לעיל כד לג) עד אם דברתי דברי: **לרעה.** לרעה אי אתה עובר, אבל אתה עובר לפרקמטיא:
@144 **אלהי אברהם.** קדש: **ואלהי נחור.** חול: **אלהי אביהם.** חול:
@145 **ויזבח יעקב זבח.** שחט בהמות למשתה: **לאחיו.** לאוהביו שעם לבן: **לאכל לחם.** כל דבר מאכל קרוי לחם, כמו (דניאל ה א) עבד לחם רב, (ירמיה יא יט) נשחיתה עץ בלחמו:
@147 **ויפגעו בו מלאכי אלהים.** מלאכים של ארץ ישראל באו לקראתו ללוותו לארץ:
@148 **מחנים.** שתי מחנות, של חוצה לארץ שבאו עמו עד כאן, ושל ארץ ישראל שבאו לקראתו:

@1 **ויצא יעקב וגו'**. טעם שלא הספיק בהודעת הליכתו בפרשה הקודמת דכתיב (פסוק ז) וישמע יעקב וגו' וילך וגו', להודיע אשר פגע בדרך קודם הגיעו למחוז חפצו, ולצד שהפסיק בענין חזר לומר ויצא וגו'. אלא צריך לדעת למה הוצרך לומר **וילך** וגו'. ומה גם שפגיעתו במקום היתה קודם הגיעו לחרן ולא היה לו להקדים המאוחר. עוד למה אמר **חרנה** ולא אמר לחרן, והגם שאמרו ז''ל (ב''ר פס''ח) כל תיבה וכו', עם כל זה יכוין הכתוב על דבר בשנותו לפעמים:
@1 **אכן** התורה תכוין לסדר כל מה שעבר על יעקב מעת צאתו. וזה תחלה לדבר **ויצא יעקב** וגו' פי' לא עשה אלא יציאה ולא הוצרך ללכת ברגליו וההולך הוא חרנה, והוא אומרו **וילך חרנה** פי' חרנה הוא שהלך ממקומו להקביל פני יעקב:
@1 **עוד** ירמוז להודיע כי כשיצא יעקב מבאר שבע תכף הלך חרונו של עשו, והוא אומרו **וילך חרנה**. ולדבריהם ז''ל ששלח עשו אליפז אחריו וכו', ירצה באומרו **וילך חרנה** לרמוז על הליכת אליפז אחריו בחרון. ואולי כי לזה סמך לדבר ויפגע במקום לרמוז כי ראה עצמו בצער והוצרך לתפלה:
@2 **ויפגע במקום**. פשטו של מקרא שפגע במקום אחד של ישוב. וכמו שתמצא שגמר אומר הכתוב לבסוף דכתיב ואולם לוז שם העיר הרי כי עיר היתה וילן שם בעיר ההיא. ואומרו **כי בא השמש** לומר שזולת זה היה הולך הוא להגיע למחוז חפצו במצות אביו ואמו. ורז''ל (ב''ד פס''ח) פירשו במקום הידוע הר המוריה דכתיב (לעיל כב ד) וירא את המקום וגו', וזה דרך דרש בנקודת הה''א, ודבריהם ז''ל ככתובים וכמסורים אצלינו, ואין סתירה לדברינו וכמו שפי' רש''י שנעקר הר המוריה ובא לשם, כי הוא זה מקום המקודש:
@2 **וישכב במקום ההוא**. הודיע זה לומר ויחלום וגו', ואמר **במקום ההוא**, כי לא השכיבה היא דבר הסובב לחלום אלא לצד המקום ההוא כי היה מקום מקודש כמו שאמר לבסוף:
@2 **עוד** ירמוז באומרו **וישכב במקום** על דרך אומרם ז''ל (חולין צא:) שקפל הארץ תחתיו, לזה אמר וישכב במקום ההוא פי' כולו שכב בו כאומרו (יג) אשר אתה שוכב עליה:
@3 **ויחלום והנה וגו'**. טעם אומרו **והנה**. להיות שאין החלום מוחלט בבחינת הצדק כי חלומות שוא הם, גם שעל כל פנים יהיה בהם תבן כי הם במראה השעמום, לזה אמר והנה פי' כי הדברים בלא שעמום ודמיונות אלא כל דבר נגלה אצלו ומבואר כיום יאיר, ואין זה דומה לשאר החלומות שרואה דבר ואינו מחליט בראייתו מה שהוא רואה, ולזה תמצא שדקדק לומר בכל פרט ופרט מהנגלה אליו בחלום והנה, גבי ראית הסולם אמר **והנה** סולם, גבי ראית המלאכים אמר **והנה** מלאכי וגו', גבי גילוי שכינה אמר **והנה** ה', הכוונה בזה כי היתה נבואה ממש:
@4 **והנה ה' נצב עליו**. ירמוז גם על יעקב, על דרך אומרם ז''ל (ב''ר פמז) האבות הם מרכבה לשכינה, ולהיות שהוא רגל רביעי יאמר בדיוק נצב עליו יותר מעל אברהם ויצחק כי הוא עיקר העמדת הכסא:
@4 **אלהי אברהם אביך וגו'**. טעם אומרו אביך ללא צורך, גם דייק לומר אביך באברהם ולא אמר אברהם ויצחק אבותיך, נתכוין למעט עשו מירושת אברהם ועשה יעקב הוא היורש אברהם לא שתגיע הירושה ליצחק וממנו ירשנה יעקב שאם כן תגיע הירושה לעשו, וחששת ישמעאל אינה, כי כבר כתבתי (לעיל טז) שמשפט עבד יש לו דכתיב (לעיל כא) בן האמה ולא בנך וגופו קנוי ליצחק, ואין טענת עשו בו כי ירושת אברהם נתנה ליעקב ולא לעשו. והגם שבן מומר יורש את אביו דבר תורה (קידושין יח.) כאן כשנתן ה' לאברהם מתנות וברכות וכדומה נתנם לו על מנת שאחריו ליעקב כאומרו (לעיל כא יב) כי ביצחק יקרא לך זרע (נדרים לא.). והגם ששם זרע לא יריע לנחלה שיירש הגם שאינו נקרא זרעו, הרי מצינו שזרע פסול יקרא גם כן זרע כדאיתא בסנהדרין (סד:) כי מזרעו נתן למולך לרבות זרע פסול הרי שיקרא זרע. אלא דסתם זרע הוא כשר וכשממעט כאן עשו שלא יקרא זרע מיעט אפילו זרע פסול לא יקרא לו, וממוצא דבר אתה למד שאין לו בו ירושה. וכמו שגילה ה' לבסוף שנותן ליעקב כל ברכות אברהם. ומה שלמדו בש''ס (קידושין יח.) מפסוק כי ירושה לעשו נתתי וגו', היינו שירשוהו בניו לעשו לא שעשו ירש ח''ו כי פשיטא שאין לו חלק ונחלה באברהם:
@5 **ונברכו בך כל משפחות וגו'**. שכן מצינו בארם שנתברכו בו כאומרם ז''ל שם (ב''ר פ''ע) וז''ל שקודם בא יעקב היו מדוחקים למים וכיון שבא נתברכו במים, וכן גם כן במצרים מעת שירד נתבטלה גזירת הרעב, ונתברכו לרגלו. ואומרו **ובזרעך** שכל זמן שהיה בית המקדש קיים היתה ברכת ע' אומות וקיומם באמצעות ישראל שהיו מקריבין ע' פרים בחג (סוכה נה:), ובגליות גם כן קיום האומות וסמיכתם היא ישראל דכתיב (שה''ש א) שמוני נוטרה את הכרמים וגו':
@5 **ובדרך** רמז כל הפרשה תרמוז ענין האדם, וכמו שהתחילו לומר בה רז''ל (זהר חלק א קמז) **ויצא יעקב** היא הנפש בצאתה מעולם העליון, ונקרא יעקב על שם יצר הרע הכרוך כעקביו. ואומרו **מבאר שבע** מקום שממנו יצאו הנשמות יקרא באר מים חיים, **ושבע** ירמוז אל שבועת ה' אשר תשבע הנפש בצאתה שלא תעבור על דבר תורה (נדה ל:), ואומר **וילך חרנה** על דרך אומרם ז''ל (סנהדרין צא:) כי יצר הרע יכנס באדם בצאתו מרחם אמו דכתיב (לעיל ד' ז') לפתח וגו', ואומרו **ויפגע במקום** כי צריך האדם להתפלל לה' שהוא מקומו של עולם שלא יעזבנו בידו. ואומרו **וילן שם כי בא השמש** שצריך להתנהג כן עד לכתו מעולם הזה כשיעריב שמשו, והוא אומרם ז''ל (אבות פ''ב) אל תאמן בעצמך עד יום מותך, ואומרו **ויקח מאבני המקום** על דרך אומרם ז''ל (ברכות ה:) וז''ל אמר ר' שמעון בן לקיש לעולם ירגיז אדם יצר הטוב וכו' ואם לאו יעסוק בתורה דכתיב (תהלים ד) אמרו בלבבכם והוא אומרו מאבני המקום פי' בניינו של עולם שהם דברי תורה, גם יתיחם להם אבני המקום שבהם נסקל ונרגם יצר הרע וכחותיו, והוא אומרם ז''ל (סוטה כא.) תורה מצלת מיצר הרע בין בזמן שעוסק בה בין בזמן שאינו עוסק בה. ואומרו **וישם מראשותיו** יכוין על דרך מה שאמר רשב''ל אם לא נצחו יקרא קריאת שמע שעל המטה שנאמר על משכבכם. ואומרו **וישכב במקום ההוא** יכוין למה שסיים רשב''ל לא נצחו יזכור לו יום המיתה, והוא אומרו **וישכב** שכיבה הידועה במקום הידוע דרך כל הארץ בית מועד לכל חי, ואחר כל התנאים הללו מובטח הוא שינצח היצה''ר, ומעתה מבשרו הכתוב שיהיה ראוי לענף מענפי הנבואה שיגלה ה' אליו בחלום ידבר בו, וצא ולמד חלומותיו של ר' אלעזר בן ערך המובאים בספר הזוהר (ח''א קלט ובז''ח לך כה.). והסולם הוא סוד נפש אדם ולהיות שבצאת נפש מאדם בשוכבו לא תעקר בהחלט מגופו של אדם אלא חלק ממנה בגוף, והוא אומרו **מוצב ארצה וחלק מגיע השמימה**, והעד על זה כשיהיה האדם ישן יקיץ על ידי התנועעות הגוף הישן ואם נפש האדם נפרדה והלכה לה לא תרגיש בהתנועעות הגוף אלא ודאי כי מוצבת ארצה וראשה מגיע השמימה פי' שאין מפסיק בינה ובין השמים, כיון שיצר הרע באדם אין, תגיע הנשמה לשמים. ואומרו **מלאכי אלהים עולים** וגו' ירמוז אל בחינת מעשים טובים אשר ישתדל אדם בעולם הזה ויעלה באמצעותה אורות עליונים בשורש נשמתן והם נקראים בדבריהם ז''ל (זהר ח''א יח) מיין נוקבין להם יקרא מלאכי אלהים, וכן הוא במשנת חסידים (אבות פ''ד) העושה מצוה אחת קנה לו פרקליט אחד, ובעלות אלו ירדו מיין דכורין כי בהתעוררות התחתונים יתעוררו מים העליונים להשפיע אורות נוראים בסוד נשמתו, והוא אומרו **ויורדים בו**. ואומרו **והנה ה' נצב** פי' שממדרגה זו יעלה לנבואה עצמה ולא בחלום ידבר בו אלא תגלה עליו השכינה, ולזה תמצא שאמרו ז''ל (רמב''ם הל' תשובה פ''ה) על ישראל שלא הושלל אחד מהם מהנבואה וכולן מוכשרים לדבר זה:
@7 **וייקץ וגו' אכן וגו' ואנכי וגו'**. צריך לדעת כוונת אומרו **אכן**, שנראה כי נתגלה לו הנעלם. עוד מה תמיהא זו **ואנכי לא ידעתי** שנראה שצריך הוא לדעת כל נסתר. ויתבאר על דרך אומרם ז''ל (חולין צא:) כי בא השמש שקעה לו שלא בעונתה לשכב שם בבית מלון המאושר, ויעקב לא הרגיש טעם הערב שמש שלא בזמנו, לזה כשבא החלום ברוב ענין אז הוכר לו הנסתר טעם הערב שמש, והוא אומרו אכן יש ה' וגו' ולזה העריב השמש לצורך שכיבה במקום הזה. ואומרו **יש ה'** פי' שם הוא מקום שבו ה' מצוי תמיד יותר מכל המקומות, ואשר לזה רצה ה' לדבר אתו שם מדי עוברו שמה, ואמר ואנכי לא ידעתי קודם טעם הדבר כי אם היה יודע היה מכין עצמו לנבואה כי הנבואה צריכה הכנה כידוע. ואפשר אם היה מכין עצמו היה מתנבא בהקיץ ולא בחלום ידבר בו, ולזה מתאונן על מה שלא השכיל על דבר. ורש''י ז''ל פי' ואם ידעתי לא ישנתי במקום קדוש ע''כ. ואם לזה לבד נתכוין נאמר אליו ואם לא ישנת לא היית חולם חלום נבואיי בכל ההבטחות, ובהכרח להשלים הכוונה במה שפירשתי:
@8 **ויירא ויאמר וגו'**. פי' הרגיש בלבו שהיה ירא מעצמו, ואמר כמה מורא במקום הזה, ונתן טעם באומרו **אין זה כי אם בית אלהים**, דקדק לומר שם אלהים כי הוא מקור המורא דכתיב (קהלת ג) והאלהים עשה שייראו וגו', ודבר ידוע כי שם אלהים יפחיד לבב אנוש, ואומרו **וזה שער** וגו' פי' מקום המכוון כנגדו למעלה הוא שער השמים, ולזה אמר פעם ב' וזה. עוד נתכוון לתת טעם למעלת המקום שנשתנה למעלה אין זה כי אם בית אלהים אשר קדמה אליו הידיעה כי בחר לו יה בית לשכון שמה ואמר כי הוא זה המקום, והוכיח עוד כי הוא זה בית הבחירה כאומרו וזה שער השמים כי ראה שהיו מלאכים עולים ויורדים וקדמה הידיעה אצלו כי המקום המקודש הוא מכוון כנגד שער השמים:
@11 **וידר יעקב נדר לאמר**. פי' שהוציא הנדר בשפתיו כי זולת זה נדר בלב אינו נדר:
@11 **אם יהיה וגו'**. אם זה תתפרש על דרך מה שאמרו ז''ל (ב''ק פ''ד מ''ה) בפסוק (שמות כ''א) אם כופר, אם כסף תלוה (שם כב) שאינו ספק אלא ודאי וכאלו אמר כאשר יהיה זה וגו' (מכילתא ס''פ יתרו):
@11 **עוד** ירצה על זה הדרך אם תסכים מדת הדין על הדבר, והוא אומרו **אם יהיה אלהים**, כי לא דבר אליו אלא ממדת הרחמים דכתיב והנה ה' נצב וגו' הנה אנכי עמך ודבר ידוע כי מדת הרחמים תסכים להטיב ומדת הדין תעכב בדבר לזה אמר אם יהיה אלהים וגו':
@12 **והיה ה' לי לאלהים**. ועד עתה אינו לאלהים ח''ו. ורש''י ז''ל פירש שלא ימצא פסול בזרעי, ואין אני יודע היכן רמוז דבר זה באומרו והיה וגו'. ועוד הבטחה זו תמיד היא תלויה ועומדת ואימתי יהיה קץ הגבול לעשות האבן מצבה. והנכון הוא שנתכוון לומר שיתיחד אליו שם ה' לאלהים כדרך שנתיחד על אבותיו (פסוק י''ג) אלהי אברהם אלהי יצחק גם יאמר עליו אלהי יעקב, והוא אומרו **לי לאלהים** פי' לי בייחוד. ודבר גדול דבר יעקב בזה, ותמצא שכן היה דכתיב (ל''ג כ') ויקרא לו אל אלהי ישראל ואחר כך שלם נדרו אשר נדר לעשות אבן הזאת:
@13 **והאבן הזאת וגו'**. יראה כי היא זו אבן השתיה (זהר ח''א ע''ב.) שהזמינה למקדש, ומצינו לו שהזמין עצי שטים למשכן במדבר. (תנחומא תרומה) ואולי שיכוין ה' באומרו ועשו לי מקדש לשון מזומן פירוש מה שכבר הוזמן כי המשכן וגם בית המקדש בשניהם הזמינם יעקב, ושכנתי בתוכם חוזר אל שני הכנות אלו:
@14 **וישא יעקב רגליו**. נתכוין בזה כי עני היה ולא היה לו לישא רק רגליו, ואשר לזה כל אשר יהיה לו בחזקת שאינו מעושר וחייב לעשרו ב' מעשרות כאומרו עשר אעשרנו ואמרו ז''ל (כתובות נ.) מעשר בתרא כמעשר קמא והוא החומש:
@14 **עוד** ירצה כי לא הוצרך ללכת אלא נשא רגליו ותכף הלכה אצלו ארצה בני קדם, ולזה לא אמר לארץ בני קדם:
@14 **וטעם** אומרו **בני קדם** ולא אמר לחרן, כי לא נזדמנה לו חרן אלא ארץ בני קדם שבה היתה עיר חרן, ומה' היתה זאת כדי ששם תזדמן לו רחל וידע מה שידע שם ממנה וכל העובר ביניהם לדבריהם ז''ל (מגילה י''ג):
@15 **והאבן גדולה**. פי' הכתוב יודיע שהאבן גדולה היא ואם היה אומר ואבן גדולה לא היה המשמעות שמכוין הכתוב להגיד גדולתה אלא שמגיד שהיתה על פי הבאר אבן גדולה לשלול קטנה, מה שאין כן מאומרו והאבן גדולה לא בא הכתוב אלא להגיד הפלגת גדולתה, ומכוון הדבר להודיע עזר אלהי שבכח יעקב דכתיב ויגל את האבן ודרשו ז''ל (ב''ר פ' ע') כאדם המעביר פקק מעל פי צלוחית:
@19 **ויאמר להם השלום וגו' והנה רחל וגו'**. טעם שלא אמרו **שלום לו** כלשון השאלה. להיות שיש במשמעות דברי יעקב ב' דברים. א, הוא אם שלם בגופו ובממונו. וב, אם הם שלמים עמו. ופי' דבריו השלום אתם אליו, ולזה נתחכמו ואמרו שלום פי' לכל מה שאתה שואל שלום. וטעם אומרם **והנה רחל** תשובה למה שלא שאל, אולי שלא להאריך עמהם בשאלות אמרו הנה רחל בתו ולה תשאל:
@19 **עוד** יכוונו לומר כי לצד שלומו עמהם שהוא שולח בת קטנה עם הצאן מה שלא היה ביתרו שהיה שולח ז' בנותיו ואף על פי כן היו הרועים מגרשים אותם:
@19 **עוד** נתכוונו לומר לו **שלום** פי' למה שנוגע לגופו ולמצבו עמנו שלום, וכדי שלא יבין שרצונם לומר כי הוא בעושר ובנכסים גמרו אומר **והנה רחל** וגו' וממוצא דבר ידע כי לא אמיד בנכסים הוא כי צריך לבתו לרעות, וגם שמספקת בת אחת לרעות צאנו כי מעט הם. וכוונתם בדקדוק הדברים היא כדי שלא יוציאו מפיהם דבר שקר בדבר שעתיד להתגלות. או שחששו שיאמר להם לבן למה הוציאו עליו קול עושר, ומטעם עצמו שאמר הכתוב (משלי כז) מברך רעהו בקול גדול וגו' שלא יתארחו אצלו הרבה ויעני:
@19 **או** אפשר שכוונתם להודיע ליעקב כי לבן כילי הוא בממונו ומזלזל בעצמו שתרעה לו צאנו בתו היקרה ומזה יקיש לדעת את האיש ומעשהו:
@20 **ויאמר הן עוד וגו'**. טעמו אשר נעשה שופט להם, הוא לצד צער בעלי חיים דבר תורה (ב''מ לב:) וחש על הצאן. ועוד רצה לדעת אם טעם עכבתם היא לצד שאין זמן להשקות הצאן ולרעות כי העיר רחוקה היא והצאן בייתות הנה, ודבר זה נוגע לו לדעת דרך בא בו, ומתשובתם ידע כי לא לסיבת ריחוק העיר הם עושים:
@22 **עודנו מדבר עמם**. הנה לפי סדר הכתוב הם המדברים אליו והיה לו לומר עודם מדברים עמו כי אחר תשובתם באה, ואולי כי לצד שעיקר סיפור הענין הוא הודעת העובר על יעקב לזה תלה הדבר בעיקרו שהוא יעקב:
@22 **או** יכוין הכתוב לומר שביאת רחל היתה בעוד שהוא מדבר עמם קודם שישיבו אותו דבר באה אלא שהכתוב גמר אומר מה שהשיבוהו בתשובתם ואחר כך הודיע ביאתה, ורשם זמנו כי הוא בעת שהיה הוא מדבר עמם:
@22 **עם הצאן אשר לאביה**. פי' כל הצאן שהיו לו, הרי זה עדות ליעקב שאמר (לקמן ל' ל') כי מעט אשר היה לך לפני וגו' כי בת קטנה נוהגת בם:
@22 **או** יאמר שכל הצאן היתה מספקת היא להם **כי רועה היא** פי' בקיאה ברעיית הצאן. ולפי' ראשון אומרו **כי רועה היא** פי' ואף על פי כן היו מועט וזולת זה ספו תמו:
@22 **או** יאמר **כי רועה היא** ניחש נחשיו והשכיל כי יצליחו הצאן ברעייתה וזולת זה לא היה מזלזל בבתו יפת תואר ויפת מראה לרעות צאן:
@22 **עוד** ירצה על זה הדרך **ורחל באה** ולא תאמר כי ח''ו יצאנית היתה אלא לטעם כי היא רועה אותם ולזה יצתה עם הצאן:
@23 **ויהי כאשר** וגו'. טעם אומרו שלשה פעמים **אחי אמו** ללא צורך. לומר שכל מעשיו היו לצד היותו אחי אמו ולכבוד אמו. או לצד החשד שיראוהו עושה חסד עם רחל והוא איש נכרי לזה היה מוציא מפיו טעם הדבר, בראותו רחל אמר בת לבן אחי אמו, הצאן של לבן אחי אמו, ובעת ההשקאה גם כן שבזה הסיר מעליו חשד דבר, ובעת שנשק לא אמר כי כבר אמר, ועוד בכיו יגיד עליו כי אחים היו:
@23 **עוד** ירצה על דרך אומרם ז''ל (ע''ז כו.) האומות לא מעלין ולא מורידין, לזה אמר **וישק את צאן לבן**, וטעם (משלי יד) חסד לאומים, לצד היותם אחי אמו בשביל כבוד אמו השקה:
@25 **ויגד יעקב וגו'**. פי' הגיד לה ב' בחינות הקורבה שהיו לרחל, א' קורבת הגוף והוא אומרו **כי אחי אביה הוא**, והב' קורבת הנפש והוא אומרו **וכי בן רבקה הוא**, וידועה רבקה בצדקותיה, והצדיקים ישמחו בדומה:
@25 **עוד** ירמוז על דרך אומרם ז''ל (מגילה יג:) שאמרה לו אביה רמאי והוא השיב כי אחיו הוא ברמאות, וכפי זה חש יעקב כי תאמר עליו גנאי הוא הדבר שיתנהג צדיק עם רשע כרשעתו, לזה אמר **וכי בן רבקה** פי' שיתחכם עליו בדרך צדק ואמת להוציא בולעו מפיו ולנצחו במשפטיו, והוא סוד (קהלת ז') החכמה תחיה בעליה ולא ירמהו בדרך רשע ומיאוס אשר יכלם בעשותו ככה:
@26 **ויהי כשמוע לבן וגו'**. אומרו **ויהי** לשון צער. רמז שנתכוין לרעה כאומרם ז''ל (ב''ר פ' ז') שיצא לגוזלו וחפש מצפוניו וגם חבקו לדעת את אשר אתו וגם נשקו אם בפיו מרגליות. ואומרו **שמע יעקב בן אחותו** פירוש לא הגידה רחל מה שאמר לה יעקב כי הוא אחי אביה אלא היותו בן רבקה צדיק בן צדקת. ובזה חשב מחשבות לרמותו. וגם אומרו **ויביאהו אל ביתו** הטעם אולי ממונו יבא אחריו והביאו לביתו עד יגיעו נכסיו:
@26 **ויספר ללבן את כל וגו'**. סיבת בואו, וטעם בואו, ואשר עבר עליו עם אליפז כי נטל ממנו הכל ברודפו אחריו:
@26 **עוד** יתבאר על דרך אומרם ז''ל (מגילה י''ג) שרחל הודיעה את יעקב כי אביה רמאי, לזה נתחכם לספר לו כל הדברים שעברוהו כדי שבזה יחדל מהרשיע כשידע מה שנתחכם עד שלקח הבכורה והברכה ידע כי ערום יערים למה שיצטדך, וגם הודיעו אשר עברו ממעשה האבן, וזה יגיד כי הוא גבור חיל. גם מעשה השקאת צאנו, וזה יגיד חיבתו בו והנהגתו הישרה עמו:
@27 **ויאמר לו וגו' אך עצמי וגו'**. פי' עצמו ואינו עצמו כי השכיל שאינו מבחינתו שלא תדמה בבחינה כי לבן חושך ולא אור, ולזה דייק באומרו **אך עצמי** למעט. ואולי שדייק בחינות שבהם ידמה אליו שהם עצם ובשר לא הנפש:
@27 **עוד** יכוין להשיב על מה שנתכוון להודיעו כי איש חכם הוא ואמר לו **אך עצמי** פי' מיעוט ממה שהוא על דרך אומרם ז''ל (ב''ב קי.) רוב הבנים רומים, וכל דומה לא ישוה לנדמה בכל חלקיו מבלי השארות חלק אחד. ולמה שפירשתי בפסוק (כ''ז מ''ג) ברח לך אל לבן וגו' כי הוא יעמוד להצילו מידי עשו. ומן הסתם סיפר יעקב הדברים ללבן, לזה השיב שכן יעשה שהוא עצמו ובשרו וכמו (איוב יד) שאך בשרו עליו יכאב כמו כן על יעקב אם יבא עשו והכהו נפשו תאבל, ואמר **אך** למעט שלא יסתכן עליו:
@27 **וישב עמו חדש וגו'**. האריך לו זמן אולי יתגלה במשך הזמן קנייניו, וכשראה כי אין תקות ממון בירר הנהגתו עמו. עוד לפי שנתן עיניו בו לעובדו העלים עין ממנו שלשים יום ועבדו בהם חנם ואחר כך התנה עמו לטעם אשר אבאר בדבריו. עוד נתכוון לבחון אותו היצליח בדרכו, ותמצא כי מיום שנכנם אצלו העבידו, וכן הוא אומר ועבדתני חנם הא למדת שכבר עבדו וראהו כי הוא איש מצליח:
@28 **ויאמר לבן וגו' הכי אחי וגו'**. קשה מי אמר לו חנם הוא עובדו, ועוד לו יהיה כדבריו ומה בכך אם עובדו חנם, ואם רצונו לומר שהוא שונא מתנות כן יחיה, הלא מצינו שאוהב הגזל ומכל שכן שיהיה חפץ בניתן לו ברצון:
@28 **אכן** שפתותיו ברור מללו כי לא בא אלא להמעיט שכרו של יעקב, והוא על דרך מה שכתב הרמב''ם (הל' שלוחין ושותפין פ''ו ופ''ח) שכל שלא התנה הרועה עם בעל הבית יטול שכרו בחלק הפקדון שליש הריוח ובעגלים וסייחים ב' שלישים, לזה חש לבן כי טעמו של יעקב שלא בירר שדעתו ליטול שליש בגדולים וב' שלישים בעגלים וגו' ויחרד הרמאי על הדבר, והן אמת אם היה יעקב כאחד הסכלים לא יקפיד עליו שנתכוין לזה אז או שיתן דעתו אחר כך, ויעלים לבן עיניו ממנו לעובדו חנם, אלא למה שקדם לו שהודיע שיערים גם הוא עם הערום לזה רצה לגלות, והוא אומרו **הכי אחי אתה** ערום כמותי כדרך אומרו (י''ב) אחי אביה הוא וכמו שנודע לו ממעשיו אשר ספר לו. **ועבדתני חנם** פירוש היאומן שתעבוד חנם, הא ודאי שתבא בטענה לבסוף ותקח מה שראוי לקחת במשפט, לזה אני רוצה שתגלה דעתך הגידה לי וגו', וכל תנאי שבממון קיים:
@29 **וללבן שתי בנות וגו'**. נתכוין הכתוב לומר שהיו נכרות ומפורסמות שהגדולה היא לאה והקטנה **היא** רחל שלא היה יכול לומר כי הגדולה היא הקרואה רחל, גם דקדק לומר הגדולה הקטנה לומר כי לא היו בגדר להחליפם ויעשה קטנה גדולה וירמה ליעקב בתת לו לאה ויאמר כי היא הקטנה ששמה רחל כי הגדולה היתה גדולה ביותר והקטנה קטנה ביותר, והוא אומרו **הגדולה** פי' שהיתה לאה גדולה בפני עצמה לא בערך רחל לבד היתה גדולה ממנה בשנה או שנתים שההיכר אינו ברור כל כך, ורחל גם כן היתה קטנה ביותר בפני עצמה לא בערך לאה לבד כמו שתאמר כי לאה היתה בת כ' שנה ומעלה ורחל כבת ה' כבת ז', ומעתה אין מקום ללבן לרמות יעקב בתנאו:
@30 **ועיני לאה רכות וגו'**. אין ראוי לספר הכתוב גנאי הצדקת אם הבנים שבטי יה ח''ו אלא נתכוין להודיע שאין מציאות ללבן להחליפם כי משונית היתה לאה מרחל, כי לאה מלבד שלא היתה יפיפיה אלא שעוד לה שעיניה רכות והוא ענף מכיעור הגוף, ורחל לא מלבד שלא היה בה כיעור אלא שהיתה יפת תואר ויפת מראה, ומעתה הרי ננעלו בפני לבן אופן הרמאות ובטלו רמאותיו:
@30 **יפת תאר ויפת מראה**. פי' שיש ב' בחינות ביופי, הא' בכל פרט ופרט כמו שתאמר העינים האף הרקת צואר, וצא ולמד ממה שפרט שלמה המלך בשיר השירים, ובחינה ב' היא כללות הפנים וכללות הגוף, לזה אמר יפת תאר ויפת מראה שהיו פרטיה כל אחד יפה בפני עצמו וגם בדרך התקבצותם יחד:
@30 **עוד** ירצה **יפת תואר** כמשמעה, **ויפת מראה** שהיה לה חן שיתאוה לה כל רואה:
@31 **ויאהב יעקב את רחל**. פי' לא לצד יופיה אלא לצד מה שרחל בת זוגו:
@31 **או** יאמר על דרך אומרם ז''ל (שבת כה:) בדין זיווג תלמיד חכם שצריך שתהיה לו אשה נאה כנגד יצר הרע, והגם כי ישתנה יעקב למעליותא שמושלל מיצר הרע, עם כל זה התורה תלמד לאדם דעת:
@31 **אעבדך שבע שנים**. צדיק זה יכוין תמיד להכניע עצמו שבע, וגם בהשתחויתו לאחיו שבע פעמים, והוא סוד (משלי כד) שבע יפול צדיק וקם אחרי נפלו, ואולי שנתן שוויה במה ששעבד עצמו ז' שנים שהוא יותר מכדי שני עבד עברי:
@31 **ברחל בתך הקטנה**. ברחל ולא בלאה, בתך ולא רחל אחרת מן השוק, **הקטנה** שלא תחליף שמות בנותיך ותקרא לגדולה רחל, **הקטנה** אני אומר ולא הגדולה, ולא יועיל לך שינוי השם שתקרא לה רחל:
@32 **ויאמר לבן טוב תתי וגו'**. צריך לדעת לאיזה ענין אמר כן לבן. גם איך יוצדק לומר טוב תתי לך מתתי וגו' אם אחר לא יעבוד, ואולי ששקר לבן בזה ורמז לו כי יש אחר שיעבוד כמו כן בעד רחל, ועוד קשה איך יוצדק לומר תתי לשון מתנה כיון שהוא עובד בעדה שבע שנים שהוא כדי דמיה, כי הלא תדע שהקונה עבד עברי שש שנים יעבוד והרי הוא נתן שוויו בעד שווי רחל:
@32 **עוד** צריך לדעת אומרו **שבה עמדי** שהוא שפת יתר:
@32 **אכן** מחשבתו הרעה נכרת מתוך דבריו כי נתכוין לרמות לתת לו לאה כמו שעשה אחר כך, ולזה הקדים לדבר אליו כדברים האלה, וזה הוא שיעור דבריו **טוב תתי אותה לך** אמר לשון מתנה לשלול כי אין זה מכר לומר לו לבסוף הן אותה קניתי ממך כמו שכן אמר הלא ברחל וגו' וכמו שאבאר שם בעזרת ה', וחש שיבין יעקב שבתורת מתנה מוחלטת הוא נותנה ולבסוף יבא עליו בטענת הבה שכר שבע שנים שעבד, לזה אמר כי העבודה שעובד עמו תהיה בעד מה שבוחר בו יותר מאיש אחר, וזה הוא שיעור הכתוב **טוב תתי אותה לך** ואבחר בך לצד מה שאתה עובד עמי **מתתי אותה לאיש אחר** בלא עבודה, ולעולם אין זה שוויה של רחל ולא בבחינת מכר הוא מכניסה. ואומרו **שבה עמדי** מתנה עליו שישב עמו ולא ירחיק נדוד ויעבוד מרחוק אלא עמו ישב כל זמן העבודה שתהיה עיניו פקוחות על עבודתו. עוד הערים לומר אליו שישב עמו עד עולם, וכמו שהתנה (ש''ר א') יתרו עם משה ולא הוצרך להשביעו על הדבר מפני שהם דברים הנקנים באמירה. ויתרו שהוצרך להשביעו למשה, נתכוון לחייבו אפילו תתרצה צפורה ללכת השביעו על דעתו לשבת את האיש. וטענה זו היה בדעתו לטעון כנגד יעקב כשיצטרך, ולזה צוה ה' אליו (פ' ל''א) השמר לך פן תדבר עם יעקב, ויעקב לא עשה שמירה לזה כי דברי לבן דברם אליו בדרך חיבה על זה הדרך ולמי אתן בתי טוב ממך שב בני עמדי פי' כי אנשים אחים אנחנו ולבבו לא כן יחשוב:
@33 **ויעבוד יעקב ברחל וגו'**. טעם אומרו **ברחל** פירוש היה מפרסם בשעת עבודה כי בעד רחל היה עובד והיא לו חלף עבודתו מלבן, גם מפרסם לשלול לאה לבל ישכח הדבר ותהיה כפירה בינו ובינו:
@34 **ויאמר יעקב [וגו'] הבה וגו'**. טעם אומרו **ואבואה אליה** והוא לשון בלתי נכון לצדיקו של עולם. יתבאר על דרך מה שכתב רמב''ם פ''ה מהלכות אישות הרי את מקודשת לי במלאכה זו שאעשה עמך ועשה אינה מקודשת וכו' שכל השכר מלוה והמקדש במלוה אינה מקודשת ע''כ, לזה אמר הבה וגו' והטעם לפי שלא קניתי אותה במה שעבדתי וצריך אני לקנותה בביאה שהאשה נקנית בביאה, והוא אומרו **ואבואה אליה** כי בעבודה לא קנה שהי' מלוה והמקדש במלוה אינה מקודשת:
@34 **או** יאמר על זה הדרך הלא תמצא שאמרה רחל הלא נכריות נחשבנו לו כי מכרנו, וכתב רמב''ם (הל' מכירה פ''ז) בדין לוקח עבדים וקרקעות במלוה אף על פי שאין הדמים במציאות קנה ע''כ, והוא אומרו **הבה את אשתי** פי' כבר היא אשתי כי אני סובר כהרמב''ם ומציאות שלפנינו דין מכר יש בו וכבר זכיתי בה הגם שאין הדמים בעין ומה שאני אומר לך הבה לא לגמר הקנאה שכבר קנויה היא אלא לבא עליה כדרך כל הארץ, והוא אומרו **ואבואה אליה** לשלול מדעתו לבל יחשוב שעדיין לא קנאה:
@36 **ויהי בערב וגו'**. צער גדול גרם בהטעת הצדיק וגרם פיזור תוקף הקדושה, וצא ולמד (זהר וישלח קע''ו) כי זה סיבה שנעקרה קדושת הבכור אשר בו יתקבצו מלכות וכהונה ושקל כפול בירושה, ולצד המעשה שחשב יעקב ברחל ועשה פעולתו בלאה נתפזרו בחינ' הקדושה ותחלש גבורת הקודש:
@36 **ויקח את לאה**. אולי שלא רצתה לרמות יעקב ולקחה בעל כרחה או בריצוי דברים וזולת זה לא היה צריך לומר אלא ויבא לאה בתו אליו:
@36 **ויבא אותה**. הערים להביאה בידו ולא מסרה לא לשלוחי האב ולא לשלוחי הבעל כדי שלא יהיה לו זמן להכיר בה קודם והביאה בידו ואין מהמוסר לחתן להזדמן לפניו, ושם עמד לבן עד סמוך לביאתו אליה להמעיט לו זמן ההכרה:
@36 **ויבא אליה**. טעם שלא הרגיש בה הוא לחששת צדיק וישר ונאמן רוח לבל יכשל במכשול האנושי אשר יתאוו תאוה קודם קרוב אליה ויטיפו ממנו צחצוחי טומאה קודם התחלת מצוה. ומי לנו גדול מיעקב אבינו עדות לו בתורה (לקמן מ''ט ג') ראשית אוני, ועיין מה שכתבנו שם, אשר על כן הרחיק הראות בה ותיכף ומיד בא אליה לשמור חומו בל יחלל בריתו ברית קודש, וגם אחר גמר ביאה לא הכיר בה כי כיבה הנרות כמשפט לאוהבי שמו (או''ח סי' ר''מ) עד אור הבוקר:
@37 **ללאה בתו שפחה**. קשה למה הוצרך לומר ללאה בתו ולא הספיק במה שאמר בסמוך ויתן לבן לה ומובן הדבר כי על לאה הוא אומר, מה תאמר שאין מובן אם כן למה כתב תיבת לה מקודם. עוד למה אמר שפחה ולא אמר לשפחה:
@37 **אכן** יתבאר על דרך אומרם ז''ל זלפה ובלהה נפלו בירושה לרחל ולאה מכתובת אמם, והוא שאמר הכתוב **ללאה בתו שפחה** פי' מודיע הכתוב כי שלה היא שפחה וירשה אותה מאמה. ולזה דקדק הכתוב לומר **בתו**, לרמוז כי לצד שהיתה בתו היא שקנתה שפחה זו מכתובת אמה לא שהיא קנתה אותה מאמצעות דבר אחר. ולדרך זה ידויק גם כן אומרו **ויתן לבן** שלא היה צריך להזכיר שמו ומובן מאומרו ללאה בתו כי בלבן דבר הכתוב, אלא לומר שמתנה זו אינה מתנה כפי האמת כי שלה היתה מקודם אלא לבן הוא שמחשיבה בגדר מתנה, וזה רמוז בתיבת בתו:
@38 **ויהי בבקר**. טעם אומרו לשון צער, יגיד על אשר נצטער אותו צדיק על מניעת רחל ממנו:
@38 **והנה הוא לאה**. טעם שכתוב הוא בוא''ו לרמוז דבריהם ז''ל (ב''ר פ''ע) שהיו אנשי המקום מרננים בלילה ואומרים היא לאה ובבקר הכיר הדיבור ההוא שהעירוהו אנשי המקום כי לאה היתה, גם ידוייק תיבת והנה על נכון:
@38 **מה זאת עשית וגו'**. צריך לדעת כוונתו בקבלנות מה זאת, ואם על הרמאות, הרי הוא אומר ולמה רמיתני זה יגיד כי לבד הרמאות קדם לו עוד דבר מגונה:
@38 **אכן** יעקב יקבול על ב' דברים הא' על המעשה שנתן לו לאה במקום רחל. והב' שעשה הדבר בדרך רמאות, ומגלה דעתו בזה שלא היה מקפיד כל כך אם לא היה **עושה** רמאות זה והיה עובר עליו הדרך באלמות ורשע ממה שעשה לו הרימוי, וטעם הקפדתו לצד מה שיצא לו מזה בטעותו שנתכוון אל רחל והיתה לאה ויצא מזה דברים בלתי הגונים וכמו שפירשתי בפסוק ויהי בערב (כ''ג) והצדיקים יקפידו למה שנוגע אל הרוחניות ביותר:
@38 **עוד** יכוין באומרו **ולמה רמיתני** כי יש בזה גנאי ליושבת בחיקו שתהיה נשואה בדרך רמאות וזה ירחיק חיבוב הזיווג, ולצד כי החליט בדעתו שבודאי תהיה לו תמיד לאשה הקפיד על זה:
@38 **עוד** נתחכם בדברו כדברים האלה לצד שראה כי מה שהיה היה ואין תרופה לאשר נעשה כי אין מן המוסר לטעון חזרה והסכים בדעתו לקחת גם את רחל לזה לא היה מפליג בהפרש שבין לאה לרחל שחש כי יגדיל לבן בעבודת רחל יותר ויאמר אליו נעשה תנאי מחדש וירצה לקחת יותר מז' שנים, לזה אמר **ולמה רמיתני** פי' למה עשה הדבר בדרך רמאות כי היה יכול להתרצות בלאה בלא אמצעות הרמאות כי כולן שוים לטובה:
@39 **ויאמר לבן לא יעשה כן וגו'**. צריך לדעת מה מענה בלשונו לא יעשה וגו' והלא תנאי היה הדבר אעבדך ברחל ומה ענין המנהג לכאן בדבר שהיה תנאי גמור:
@39 **אכן** נתכוון לומר כי אנשי המקום מיחו בידו מעשות כדבר הזה, והוא אומרו **לא יעשה כן במקומינו** כי היא טענת רבים:
@39 **עוד** נראה כי טענתו היא כי לא היה בפירוש בשעת התנאי שהגם שלא תנשא לאה יתן לו רחל ובזה אין סתירה למנהג מהתנאי כי לעולם תקדים לאה לינשא ובמלאות ז' שנים שיעבוד יעקב אם קדמה לאה ונשאת תיכף ומיד יקח רחל, ואם לאו יהיה יושב ומצפה עד שתקדים הבכירה כמשפטי הארץ, כי אין בתנאי דבר מגיד שהתנו לבטל המנהג, ומעתה כששאלת הבה את אשתי חשבתי שעל לאה אתה אומר כי המנהג מנהג ידוע הוא שאין לתת הצעירה קודם ומן הסתם על לאה אמרת ואין בזה רמאות ולך היה מוטל לדעת כי היא לאה מבלי צורך הודעה, ובזה ביטל טענת רמיתני. ולצד שתחשוב כי יש הפרש ביניהם, לא כן הוא כי שקולים הם אצלי ולא אשאל בעד רחל כי אם ז' שנים. ואם לצד חשקך ברחל ותקפיד על העכבה הנה היא נתונה לך תיכף ומיד אחר עבור ז' ימי משתה של לאה, והוא אומרו **מלא שבוע זאת** פי' ז' ימי משתה ותיכף אתן לך רחל במוקדם בעד עבודה שתעבוד עוד שבע שנים, וזה היה מבוקשו של יעקב שקבל עליו לא להחזיר לאה ח''ו. ויש לנו לדעת איך לא חש יעקב מקודם לטענה זו שאין דרך לתת הצעירה וכו', יש לומר שחשב שעל לבן לגלות לו הדבר וזולת זה אין דבר זה מההקפדה המעכבת כשירצה האב לתת הצעירה וכששאל הבה את אשתי מן הסתם על רחל הוא אומר והיה לו ללבן לומר אליו כי לא יכול לתת לו רחל קודם שתנשא לאה והיה הדבר תלוי ביד יעקב או להמתין עד שתנשא לאה או לקחת לאה ואין זה אלא מן השם לבן הארמי וכל טענותיו שכתבתי יש עליהם סתירה ושמו יגיד עליו:
@41 **לו לאשה**. מגיד הכתוב באומרו **לו** וגו' כי עקרת הבית היא רחל כי היא בת זוגו:
@42 **לה לשפחה**. דקדק לומר תיבת **לה**, לומר שלה היא השפחה, וכמו שפירשתי בפסוק (כ''ד) ויתן לבן את זלפה:
@42 **או** ירצה שהתנה עמה שאין זכות לבעלה בה, על דרך מה שכתב רמב''ם פכ''ב מהלכות אישות הנותן מתנה לאשה על מנת שאין לבעלה זכות בה אין הבעל אוכל פירות כי כל מה שיש לדרוש בלבן לגנאי דרשינן:
@43 **ויבא גם אל רחל**. טעם אומרו **גם** ב' פעמים, ואולי שיכוין לרבות שבא בתוספת קביעות אצלה, והוא אומרם ז''ל (ב''ר פ' צ''ח) שהיתה מטתו בקביעות אצל רחל, ולזה אמר ויבא גם אל רחל. ואומ' **ויאהב גם את רחל** פירוש מלבד תוספת האמור עוד הוסיף לה שאהבה יותר מלאה. ותמצא כי כפי הטבע ההתמדה תמעיט האהבה, וכמו שאמר הכתוב (משלי כה) פן ישבעך ושנאך, וההרחקה תוליד התאוה, והוא סוד (שם) מים גנובים ימתקו, ולזה רמז הכתוב באומרו **ויבא גם אל רחל** בתוספת קביעות ואף על פי כן גם אהב אותה ולא נתמעטה האהבה מצד זה הגם שהיה מתמיד אצלה ולא אצל לאה. ושיעור תיבת **מלאה** הוא מלאהוב לאה:
@44 **וירא ה' כי שנואה לאה**. יכוין לומר כי ה' לבדו הוא שידע והכיר כי היא שנואה לא כן היא שלא הרגישה בשנאתה אלא שהיתה חושבת שאינה אהובה לבד כאשר אבאר מדבריה בסמוך. ורז''ל (ב''ר פ' ע''א) אמרו שנואה שהיו אומרים זו אשתו של שונא שהוא עשו דכתיב (מלאכי א) ואת עשו שנאתי, ותקרא על שמו. וכפי זה אם לא היו לה בנים היו מצדיקים הדברים כי לא בת זוגו של יעקב, לזה ויפתח רחמה. ואומרו **ורחל עקרה** פי' כולי האי ואולי יסיר שנאתה שזו אינה יולדת וזו יולדת:
@48 (לב~לג) **ותהר לאה וגו' ותהר עוד וגו'**. ראיתי לתת לב בסדר השמות כי מן הראוי להקדים הסרת השנאה ואחר כך סיבת האהבה והיא אמרה בראשון עתה יאהבני ובב' הסרת השנאה. עוד מה היא כוונתה באומרה (ל''ד) הפעם ילוה וכי מקודם לא נתלוה לה:
@48 **אכן** הצדקת ע''ה לצד שקדם לה המאמר שעליו חלתה בעיניה כי היא חלקו של עשו, והגם שראתה שנשאת ליעקב אין דבר זה מצדיק בלבה כי היא בת זוגו, ולזה כשראתה שניתן לה בן אמרה ודאי כי לצד רחמי ה' עליה לצד שלא היתה אהובה כי הצדיקים יקיימו מצות חכמים (אבות פ''א ו') לדון לכף זכות, ולזה היתה תמיד דנה לכף זכות ולא עלה על דעתה כי היתה שנואה וכמו שפירשתי בפסוק (ל''א) וירא ה' וגו' ולא כן היתה דעתה, וזו היא מדת המאושרים, אשר על כן כשניתן לה בן ראשון אמרה כי זה בא להשלים החסר שהיא האהבה, וכשראתה שהוסיף ה' ונתן לה בן ב' אמרה למפרע טועה הייתי במה שחשבתי שלא היה לי אלא מחוסר האהבה והרי שמע ה' פירוש מה שלא הבנתי אני כי שנואה אנכי לזה נתן ב', אחד להסיר השנאה ואחד להכניס האהבה, ולזה אמרה (ל''ג) **כי שמעה' כי שנואה** וגו', וכשנתן לה בן ג' אמרה מעתה אין טעם בדבר אלא הרי זה בא ללמד כי לא בדרך טעות היו נשואיה כי אם אשתו זאת, והוא אומרה **הפעם** יצדיק להתלוות לה בתורת אישות כי אם צד הסרת השנאה ונתינת האהבה משום כלימתי עשה ה' היה מספיק בב' בנים ומעתה בג' הוי חזקה כי אני בת זוגו ונישואיה מה' יצא הדבר:
@48 **עוד** נתכוונה באומרה **ילוה אישי** כי גם בזמן יציאתה מעולם הזה לא תפרד ממנו להיותה בת זוגו וכמאמרם ז''ל (זהר משפטים קב.) כי הזוגות יתלוו בעולם העליון בתמידות, ואמרה הטעם כי ילדתי לו ג' בנים ובג' הוי חזקה כי בת זוגו אני, עוד שצפתה ברוח הקודש שד' נשים יהיו ליעקב וכפי זה עולים לה כפי החשבון ג', וכשניתן לה בן ד' אמרה (ל''ה) **הפעם אודה את ה'** כי עד עתה היה עושה לה משפט הצריך אבל הפעם הזאת אין זה אלא הפלגת טובתו יתברך וברכה על רוב טובה:
@49 **ותרא רחל וגו'**. דקדק לומר **ליעקב** כי הוא בחון שאינו עקר ובזה אין לתלות בו אלא בה. ואומר **ותקנא באחותה** פי' לצד שהיא אחותה ומן הסתם תדמה במזגה וטבעה אליה וזו ילדה וזו לא, שאם לא היתה אחותה היתה תולה לומר כי טעם שלא ילדה הוא לצד שלא הושוו המזגים וכדומה:
@49 **עוד** ירצה באומרו **ליעקב** כי עיקר הקפדתה היא להיותו יעקב שאם היה אדם אחר שאינו מפורסם בצדקות היתה תולה בו שהטעם הוא (תהלים קכה) כי לא ינוח שבט הרשע על גורל הצדיקים להיותה היא צדקת, וזה הי' סיבת מניעת ההריון מה שאין כן היותו יעקב צדיק מובהק לזה נתקנאה באחותה שזכתה לזה:
@50 **ויחר אף וגו'**. הטעם לפי שהוציאה מפיה דבר קללה שאמרה מתה אנכי, ודברי הצדיקים אפילו בסדר זה יעשו **רושם**, וצא ולמד (ב''ר ע''ד) ממה שקלל הוא על תנאי וכו', לזה חרה אפו, ולזה דקדק לומר **ברחל** פי' בשבילה, גם לפי שאמרה הבה לי וגו' ולא אמרה התפלל עלי:
@51 **ותאמר הנה אמתי וגו'**. דקדקה לומר **אמתי** קודם שהזכירה ביאתו אליה ולא אמרה בא אל אמתי כמו שאמרה שרה כמו שפירשתי שם, (ט''ז ה') נתכוונה לומר שאחר שיבא אליה לא תקרא אמתה עוד, ולזה אמר אחר כך ותתן לו בלהה שפחתה לאשה, אישות יש לו בה ובניה בני חורין. וכמו כן עשתה לאה שנתנה לו לאשה ונעקר מזלפה שם שפחה:
@51 **ומה** שמצינו לשרה (ט''ז ג') שהזכירה גם כן שם אישות על הגר, שבירתה בצדה במה שדקדקה לומר תיבת לו, ועיין מה שכתבתי שם מה שלא אמרה כן רחל:
@51 **ומה** שתמצא שמזכיר הכתוב (פסוק ז') אחר כך בלהה שפחת רחל וגו'. פי' שהיתה שפחת רחל, גם יכוין הכתוב שם להזכיר שם הצדקות שנתנו האמהות לבעליהן. ולא חש הכתוב לטעות, שסמך היות הדבר מבואר בכתובים הקודמים, ועיין מה שכתבתי בפרשת וישב (ל''ז ב'):
@63 **המעט קחתך וגו'**. כוונת לאה היא על דרך אומרם ז''ל (ב''ר פ' צ''ח) כי קביעות מטתו של יעקב היה אצל רחל, ולזה אמרה המעט קחתך את אישי פירוש חלק העודף אצלך הוא נגרע מחלק לאה, ואומרה **ולקחת** וגו' תכוון לומר כי בחינת הלידה תתהוה מרוב זיקוק ומהתמדת שכיבת הבעל וכמאמרם ז''ל (חולין יא:) בכמה מקומות, ומעשה הדודאים הם סגולה ללידה (זהר ח''א קנז.) לזה אמרה די לך קיחת אישי בתמידות אצלך כנזכר ולמה תוסיף קחת דודאי בני:
@63 **וטעם** יעקב שהיה עושה הפרש בין ב' נשיו לצד שאין עליו חיוב לאה זולת עונה האמורה בתורה (משפטים כ''א י') לא יגרע כי לא נשאה ברצונו ובידיעתו וכמעשה שהיה, מה שאין כן רחל אשתו זאת ובה עבד פעם ראשונה ושניה:
@63 **לכן ישכב וגו'**. יראה כי ברצון רחל היה הדבר תלוי, ואומר' לכן פי' על נתינתך לי דודאים וכו':
@63 **או** ירצה לשון שבועה משום שהם דברים שאין נקנים אלא בשבועה כי לא הקנית לה דבר שיש בו ממש, ועיין מה שכתבתי בפסוק (כ''ה ל''ג) השבעה לי במכר בכורת עשו:
@64 **ותצא לאה וגו'**. טעם עשותה ככה ולא מן המוסר, לפי מה שפירשתי בתיבת לכן שאמרה רחל שהוא על כן, חששה לאה שתחזור בה רחל ולזה קדמה ויצתה, ולפי מה שפירשתי לכן שבועה, לצד שלא דקדקה רחל לומר הלילה הזאת חששה שתדחה אותה ללילה אחרת והרי זו זריזה ונשכרת:
@64 **עוד** יש לתת טעם ללאה כי מדת חסידות עשתה שלא הניחה עד שיכנם אותו צדיק לאהל רחל ותוציאנו משם כי יש בזה הקפדה וצער גדול לרחל וקנאה גדולה, לזה קדמה קודם שיכנס אצלה, ואין זה אלא מדה טובה וחסידה וכל מגמתה של אותה צדקת להעמיד נטעי נאמן, וה' עד בדבר כי נתן שכרה דכתיב וישמע, וגו' ועיין בסמוך מה שפירשתי (ס''א שפירש''י) בפסוק זה:
@64 **שכור שכרתיך וגו'**. פירוש נתתי שכר לזולת בעדך עוד נתכוונה ששכרה ב' דברים לינה וזיקה:
@64 **בלילה הוא**. פי' ברצונו ודעתו שהסכים על הדבר:
@65 **וישמע אלהים**. מגיד שהתפללה לה':
@65 **עוד** ירצה כי הבין וידע כונתה במעשה שהוא לתכלית מצוה ואהבתה בהקב''ה ובמצותיו וקלקלה השורה במעשה זה גם ה' קלקל השורה כי כפי השורה לא היו עולים לה אלא ד' ותהר ותלד בן חמישי יותר מהשורה ובן ששי מדה כנגד מדה:
@70 **ויזכור אלהים וגו'**. מגיד הכתוב כי הגם שעלה זכרונה לפניו עוד הוצרכה לתפלה כאומרו וישמע אליה וגו':
@70 **עוד** יודיע הכתוב כי ה' זוכר את חסידיו מבלי שיצעקו אליו, לזה אמר **ויזכור** וגו' ואחר כך **וישמע** וגו' לומר שקודם שהתפללה עלה זכרונה לפניו יתברך:
@80 **הסר משם וגו'**. מדבריו מוכח כי לא יהיה לחלקו אלא נקודים וטלואים בכשבים ובעזים וחום בכשבים אבל עקודים אינם לחלקו, וממה שאמר הכתוב בסמוך משמע שלקח גם העקודים:
@80 **ונראה** כי יעקב בתנאו לא רצה שיטול בחלקו עקודים. וטעמו הוא כי אם יקח גם העקודים יצטרך להסירו גם כן מצאן לבן, ומעתה אין סימן הלובן בכל הצאן ליחמנה הצאן אליו והרי הוא יגיע לריק, כי לא עלה על דעתו של יעקב לרמות לבן בשום אופן בעולם וחשב שבאמצעות העקוד ימצא שיחמו הצאן לילד גם כן הנקוד והטלוא שהוא לוקח לעצמו. וכמו כן תמצא שאמר הכתוב (מ') ויתן פני הצאן אל עקוד והיו יולדות נקודים וטלואים והחום שיחמו אל הנימור, והרמאי לבן נתחכם לדעת זו ונטל הכל עקוד נקוד וטלוא, עוד נתחכם והסיר כל אשר לבן בו תפחנה עצמותיו כי לא כן היה התנאי שאם כן מנין יצאו עקוד או נקוד או טלוא, ומעתה פקע שכרו של יעקב. מטעם זה נתחכם יעקב לקחת שכר טורחו ויצג המקלות ולקח לעצמו גם העקודים, כי ממה שהסירם לבן גילה דעתו כי באלה חלק יעקב, והוא אומרו (ל''ט) ותלדנה הצאן עקודים נקודים וטלואים וכל שלשת המינים בחלקו של יעקב, ועל לבן נאמר (משלי ה') ובחבלי חטאתו יתמך:
@88 **פני הצאן אל עקוד**. טעם שלא אמר אל נקוד או אל טלוא אולי כי יותר יחמו הצאן אל מין זה מהב' אחרים:
@88 **וישת לו עדרים וגו'**. נתכוון בזה כדי שתמיד לא יהיו הצאן מסתכלין אלא באותן מינים ולא בשאר מינים שבזה לא ילדו כלל כי אם מאותו המין, שאם לא כן יצטרך יעקב לתת מצאנו ללבן כשתלדנה מין שאינו עקוד וטלוא וכו':
@89 **והיה בכל יחם וגו'**. צריך לדעת למה יעשה יעקב ככה בשלמא מה שעשה בתחילה בהצגת המקלות היה לצד ההכרח שזולת זה היה יגע לריק כמו שכתבנו, לא כן אחר שהיו בצאן עקודים ונקודים וגו' לא היה לו ליטול הוא המקושרות וכו' שנמצא כפי זה הוא נוטל יותר מחצי ריוח ואינו מן הדין שכל שלא התנה עם בעל הצאן מן הסתם אין לרועה ליטול אלא שליש הריוח וכמו שכתבנו בפירוש פסוק (כ''ט ט''ו) הכי אחי אתה, וכאן אין ליעקב להציל מהרמאי אלא דבר שנוגע לו בדין מן הסתם ורואני כי נוטל יותר מחצי. ואולי כי צאן המקושרות לא היו יולדות הכל עקודים וגו' אלא (מן) [על] הרוב והיה לבן נוטל חלק אחד במקושרות וכל חלק העטופים והיה מגיע לחלקו ב' שלישים, והגם שאמר הכתוב והקשורים ליעקב פי' רוב הקשורים, או שנתכוין להציל שאר גזילות שהיה עושה לו:
@93 (ג) **וירא יעקב וגו' ויאמר ה' אל יעקב**. צריך לדעת מה קשר ושייכות לב' מקראות הללו:
@93 **אכן** כוונת הכתוב היא להקדים ב' דברים שמסיבתם עשה יעקב מה שעשה שברח בלא ידיעת לבן, שזולת זה לא היה הולך בלא ידיעת לבן, או עדיין היה מתעכב שם ימים, והוא שאם לא ראה פני לבן ודבריהם שאמרו הגם שבאה אליו הנבואה ללכת היה הולך בידיעת לבן כי לא נמכר יעקב לעבד לו ולרצונו היה עמו, אלא לצד דברי בניו ופני לבן משונות היה חש שיגזול ממנו כל יגיעו, והוא שאמר לבסוף (פסוק ל''א) כי יראתי פן תגזול וגו', ואם לא היתה באה אליו הנבואה ללכת הגם שהיה שומע דברי בני לבן לא היה ממהר ללכת באותו זמן עד שיתחכם לקחת רצונו באורך הימים אז יפרד ממנו, וישב שם ימים, באופן מאמצעות ב' דברים דברי בני לבן ושינוי פניו ודברי ה' לזה עשה כל האמור בענין, לזה סמכם הכתוב יחד:
@96 **ויאמר להן רואה אנכי וגו'**. פי' ואם תאמר שיש לו טעם נכון כי הוא רואה כי שלך גדול משלו ופרצת מאוד, לזה אמר **ואלהי אבי היה עמדי** וזו ברכה מאת ה':
@98 **ואביכן וגו'**. צריך לדעת מה הוא ההתול שהיה מהתל בו, ואם עברת הדרך, זה גזלן מקרי:
@98 **ואולי** כי לבן הרגיש מפעם ראשונה שראה שילדו הצאן ברבוי מין הנוגע ליעקב בחלקו לזה נתחכם ואמר בודאי הלא דבר הוא, לזה היה אומר לו מין אחד בתחילה ואחר שיחמו הצאן היה חוזר בו בין עבור ללידה ולוקח לעצמו מין שאמר, ומיחד ליעקב מין אחר, ולזה לא יקרא אלא התול שפעמים אומר כך ופעמים וכו':
@99 **אם כה יאמר**. והגם שתנאי הראשון היה שיטול נקודים וטלואים, לא עמד בדבר אלא אחת מהנה הסכים לתת לו:
@99 **עוד** טעם הדבר הוא לצד כי מין זה של עקודים לא הוזכר בתנאי הראשון בא עליו הרשע בטענה כי לא כאלה לחלק יעקב, ולא הודה על האמת מההוכחה שנטל מין זה ולזה בפעם ראשונה הוציא מחלק יעקב עקודים ואחר כך היה מתווך עמו לרצונו להחליף מין נקודים שבחלק יעקב בחלק עקודים שהוא של לבן וחוזר חלילה עשרת מונים, ולעולם תנאי הראשון של נקודים וטלואים בכשבים ובעזים עמד במקומו:
@99 **ואומרו אם כה יאמר** לשון עתיד, לפי מה שפירשתי באומרו התל בי ידוייק על נכון, כי לא על אמירה שהיה אומר בתחילה היתה הנהגת הלידה אלא על מה שעתיד (להוליד) [לומר] באחרונה אחר עיבור הצאן, ודבר זה לא היה לצד השתדלות יעקב אלא כי מה' היתה לו וכמו שספר אחר כך שראה בחלום וכו':
@103 **העתודים וגו' עקודים נק ודים וברודים**. צריך לדעת מה הוא פי' ברודים, ולו יהיה שיהיה מין ממין הנולדים בצאן כיון שאין ליעקב חלק בו כי לא הוזכר בתנאים אם כן למה יראוהו אותו בחלום:
@103 **וראיתי** להראב''ע שכתב כי ברודים הם טלואים ולא הביא הרב הכרח לדבר. עוד לפי מה שאמר אם כה יאמר וגו' הראת לדעת כי לא היה נוטל יעקב אלא או עקודים או נקודים ומעתה למה היו עולים על הצאן מינים שאינם לחלק יעקב:
@103 **אכן** טעם הדבר הוא לצד מה שקדם לנו בידיעת לבן הרמאי כי מלבד תחבולותיו ומרמיו גם היו לו תרפים אשר יגידו לו כל דבר וכמאמרם ז''ל (תנחומא) ומן הסתם שאול ישאל בהם וידע העצמים בבטן המלאה ומראיהן ומעתה באמצעות דבר זה אפסו כוחות יעקב בכל מין אשר יתחכם יפסידוהו התרפים, אשר על כן העונה בצר ענהו, ויש לך לדעת כי מין מראה אשר יהיה בנולדים יתהוה בעת יחם ואין מציאות להפכו אחר כך זולת על ידי נס עצום להפך הטבע הפוך עצום, ודבר זה קשה בעיני אל עליון לעשותו, וצא ולמד מדבריהם ז''ל בכמה מקומות, (סוטה ב. שבת כג.) ועשה ה' חכמה שלא להצטרך להפך סדר טבע הבריאה, והוא שהיו עולים ג' מינים יחד והיה בכל נולד ונולד בכח ההיולי מוטבעים שלשתם יחד, ובזה ספו תמו ידיעות התרפים, ועם יציאת הנולדים היה נגלה בהם מין אשר יסכימו יחד כי הוא זה חלק יעקב. ולא ירחיק דעתך הדבר, כי יש עופות שיהפכו גווניהם לכמה מראות וזה הוא לצד שהטביע ה' בהם כן, וכמו כן עשה ה' בנולדים בצאן לבן להציל עשוק מיד עושק. ואומרו **ברודים** לפי מה שפירשנו מצינו ראיה לדברי ראב''ע כי הוא מין טלוא כי זולת זה דלמא יאמר לבן טלוא יהיה שכרך ונמצא הנס לבטלה ח''ו, אלא ודאי כי ברודים הוא מין טלוא ואולי לצד שלובן שלו לבן הרבה כברד נקרא כן, ומעתה נתיישב הכתוב על נכון:
@103 **כי ראיתי את כל אשר לבן וגו'**. המלאך הגיד טעם הנס כי ראה ה' כל מעשיו וערמותיו של לבן ומה שהיה מתחכם ושואל בתרפיו ולא היה מציאות להצילו ממנו זולת מעשה אשר הראהו עולים על הצאן וכמו שפירשנו:
@103 **גם** רמז לו כי כל מעשה של לבן אליו הם נתונים, ולזה לא אמר כל אשר עושה לך לבן לרמוז גם כן כי כל הנולדים יהיו לחלק יעקב, ואין בזה משום גזל כי ה' שופט צדק וידע כל אשר רימהו ואונהו והוציא מזה ונתן לזה והוא ישפוט בצדק:
@105 **העוד לנו וגו'**. כפלו לומר **חלק ונחלה**, לרמוז ב' דברים, הא' הוא חלק הנוגע להם בירושת אמם שכבר מתה, והב' נחלת אביהם, והחליטו שאין להם תוחלת משניהם והראיה הלא נכריות נחשבנו לו כבר שמכרנו זה לך האות שאין אנו אצלו במדרגת בנים וממילא יצו עליהן לבל ירשו בו. הגם שבמשפטי הגוים אפשר שהבנות ירשו ואון יוכיח וכמעשה רשב''ג ואחותו, (שבת קטז.) ואומרו **ויאכלגם אכול** ב' אכילות, א' ירושת כתובת אמם, והב' מה שעבד יעקב י''ד שנה בעדם:
@107 **אשר הציל וגו' לנו וגו'**. פי' ה' הציל ממונינו שהוא חייב לנו מידו, שלשון הצלה יאמר על גזלה מגזלן, והוא אומרו **לנו** פירוש משלנו שגזל:
@111 **ויגנוב וגו' על בלי וגו'**. קשה איך יוצדק לומר אליו שהוא בורח שאומר על בלי הגיד לו כי בורח. ואולי שהכוונה היא שנתחכם יעקב כשספר ללבן כל מעשיו והנהגותיו העלים ממנו ערמת הבריחה והוסיף לשלול אותה ממנו במה שהיה שואל ממנו לשלחו בזה היה מצדיק לבן כי לא יברח כלל, שאם לא כן למה היה שואל ממנו שישלחהו ובזה גנב לבו, והוא אומר **ויגנוב** וגו' ובמה גנב על סבת שלא הגיד לו בסיפור מעשיו כי יערים לברוח כשיצטרך לברוח. ובזה מצינו טעם בעיקר הודעת כתוב זה שבא לומר טעם שבו השיג הבריחה, כי זולת זה היה נותן לב לבן לשמור אותו מלברוח באיזה אופן שיהיה אלא שגנב לבו ובזה מצא הכנה לאסוף כל אשר יש לו וברח ואין יודע, והוא שאמר סמוך לזה ויברח הוא וכל אשר לו וגו' והבן:
@114 **דרך שבעת ימים**. יש לחקור למה נשתנה יעקב בהליכה זו שלא קפצה לו הארץ כמשפט לאוהבי שמו, ומצינו שאפילו לאליעזר עבד אביו קפצה לו הארץ, (ב''ר נ''ט) ומן הנכון אליו יאות עשות גם להצילו מהרודף ולא היה משיגו לבן. ואולי כי הגיד לו האדון ברוך הוא בזה שאין צריך לברוח כי הגם שהדביקו לבן היוכל דבר דבר אליו אפילו דיבור, וזולת זה היה מראה ח''ו כי לא יכול הצילו מיד לבן, וגדול הנס הזה שהגם שהוא בעל בחירה ימנע מעשות בחירתו ביעקב:
@114 **גם** בזה ה' סיבב כמה סיבובין כריתת ברית עמו לבל יזיק שבאמצעות הדבר נתגברו עליו ישראל בימי השופטים כשבא עליהם והוא כושן רשעתים כמאמרם ז''ל. (סנהדרין קה.) גם מזה נמשך קבורת רחל במקום ההוא כדי שתהיה לטובה אות בגלות בניה כאומרם ז''ל (ב''ר פ' כ''א) בטעם קבורתה שמה:
@121 **ועתה הלוך וגו'**. פי' להיות שמקודם קבל עליו למה נחבא לברוח שמחזיקו כבורח ואחר כך חזר לומר ועתה פי' לשון תשובה כאומרם ז''ל, (ב''ר פ' כ''א) והכונה ואם תשיבני דבר כי לא ברחת אלא הלוך כדרך הליכה הלכת **כי נכסוף נכספתה** וגו' ולא כמו שאמרתי לך בדרך בריחה אם כן למה גנבת את אלהי אלא ודאי כי לצד שהוא המגיד לחששת שמא יודיעני ויגיד לי שהלכת גנבת אותו וזה לך האות שברחת:
@122 **ויען יעקב וגו'**. פי' אין אני מכחיש שברחתי, ומה שאמרת למה וגו' כי יראתי ממך שמא תגזול וגו', ומה שהתבוננת לומר כי לסיבה זו גנבתי אלהיך לבל יגיד, לזה ענה עם אשר וגו' כי טענה זו של גניבת התרפים כי זה יגיד שבורח הוא היא טענה הנשמעת, לזה נשבע לו עליה בקללה כדין המחרים על הספק:
@123 **לא יחיה**. כדין בן נח, ואם תאמר אין צריך לאומרה הלא משפטו חרוץ, נתכוון לומר שאין לו טענה לומר כי נתונים המה לו או שכוחים המה אצלו:
@127 **ויחר ליעקב וירב**. פי' לצד שבא לכלל כעס בא לכלל מריבה וזולת זה לא היה מריב:
@127 **וירב בלבן**. פי' בערך לבן היה הדבר ניכר שהוא מריבה אבל אם היו הדברים לאדם אחר לא תקרא מריבה, וכן תמצא שאמרו ז''ל (ב''ר פ' ע''ד) וז''ל קפדנותם של אבות ולא ענותנותן של בנים וכו' פיוסים יעקב מפייס לחמיו וכו' ע''כ. וזה מכוון לדברינו. ואולי יכוין עוד שלא רב עמו בכנופיית אנשים אלא בייחוד עמו, והוא אומרו **וירב בלבן** פי' בייחוד עמו שלא יכלם בתוכחתו:
@127 **מה פשעי וגו'**. פירוש בשלמא אם מימיך מצאת בי עול שפשעתי לך (הי') [כ] כיעור זה של הגניבה בפשע ולא לבד בפשע אלא אפילו בשוגג, והוא אומרו **מה חטאתי** שתחשדני בגנב, וגילה דעתו יעקב כי טעם הקפדתו היתה שראהו ממשש כל נכסיו וכליו ולצד העדר ידיעתו בגניבת התרפים יחשב כי לא היה מחפש חיפוש מחופש אלא לראות אם לקח דבר מה משלו והערים לומר שגנבו לו תרפיו שיהיה לו סיבה לחפש בכל המקומות, לזה הוכיחו מנין נכנם לו צד הספק בו שהוצרך לחפש (לז) **מששת את כל וגו'**. פי' אפי' כלים שאין בהם מיחוש וכו' והוא אומרו **כי מששת** וגו':
@127 תרפים כמו שתאמר כלים שהם קטנים מהתרפים או המשל שהיה מחפש בכריכות שיכול להכיר מבחוץ שאין בהם תרפים הא למדת שחשדו בלקיחת כלים:
@127 **מה מצאת מכל וגו'**. פי' מכל מיני כלי ביתך בדומים שיכנס לך בו הספק לומר כי הוא שלך:
@127 **שים כה נגד וגו'**. הכוונה בזה להיות שמקודם כשטען שבא לבקש התרפים אמר אליו הכר לך מה עמדי וקח לך לחושבו כי אין מבוקשו אלא תרפיו וכשראהו שהיה מחפש ומדקדק בכל דבר ודבר אמר הא ודאי שזה חושדני וכמו שכתבתי למעלה וכל הפוסל במומו הוא פוסל והנה הוא נותן עיניו לבא בעלילה, לזה אמר אליו שים כה וגו' כי חש שיאמר על כל דבר חמדה זה שלי הוא לזה אמר **שים כה נגד אחי ואחיך ויוכיחו** פי' לאמר סימנים יצדיקו, ולא האמין באחי לבן לבדם כי כולם כיוצא בו:
@129 **זה עשרים וגו'**. טעם אומרו עשרים שנה כי לצד זמן מועט ישתמר הגנב והרמאי מעשות רע אבל לא לאורך הזמן, לזה אמר זה עשרים שנה וכולם שוים לטובה. ודבר זה אין לקחת ממנו הוכחה אם היה יעקב עם אדם בלתי מרגיש ברמאות, לזה אמר **עמך** הראית בי מימיך עול, והוכיח הוכחות מוכיחות כאשר אבאר בס''ד:
@129 **רחליך ועזיך וגו'**. צריך לדעת כוונת יעקב בזה, אם לומר פרטי ההצלחה אין זה מקומן של דברים אלו, גם אומרו **ואילי צאנך** וגו' מי יניחהו לאוכלן ואם לא ידע אדם ועד עתה מי יעיד על הדבר:
@129 **אכן** כוונת יעקב היא להיות כי דרך רועה גנב יתחכם לגנוב באומרו כי לא כל הצאן ילדו מהם ילדו ומהם שכלו ולוקחים לעצמם, ומעתה הוכחה גדולה אומרו יעקב **רחליך ועזיך לא שכלו** ובזה אין מקום לחשד שאכלתי וכו' שאם היה חפץ לאכול משלו היה לו מקום לומר לו כך וכך שכלו מהצאן, ומה' היה הדבר לשמור חסידו מחשד ולא שכלה אחת מצאנו כדי שלא יחשדנו שאכלו, וטם אומרו **אילי צאנך** התורה הוציאה גדי בלשון איל ללמוד מכאן גדי בן יומו קרוי איל, ואולי יכוין על פי מה שכתב הרמב''ם בהל' גזילה (פ''ב) וז''ל הגוזל טלה ונעשה איל וכו' הוי שינוי בידו וקנהו אף על פי שלא נתיאשו הבעלים ע''כ, לזה נתכוון לומר שאפי' בדרך שאין יכול להוציאו מידו כפי הדין לא עשה פירוש שלא גזל ממנו גדי וגדל אצלו ונעשה איל וכשהחזיר לו החזיר גדי ונמצא אכל מה שגדל ונעשה איל:
@130 **טריפה לא וגו'**. קשה איך יוצדק לומר בדבר שנטרף לשון הבאה. עוד למה כפל לומר **אנכי אחטנה מידי תבקשנה** אם הוא היה משלמה מה מקום לבקשה מידו:
@130 **אכן** כוונת יעקב היא לומר בין דבר שהוא חייב בו כפי הדין בין דבר שהוא פטור לקח ממנו לבן, ודקדק לומר טריפה כנגד זאב, ודקדק לומר לא הבאתי כנגד דריסת ארי, וכמו כן תמצא בלשון חכמים במסכת מציעא (צג.) וזה לשונם תנו רבנן שומר שהניח עדרו ובא לעיר ובא ארי ודרם זאב וטרף ע''כ, אמרו לשון טריפה בזאב כי טורף ובורח לצד שמפחד מה שאין כן הארי שבמקום שמוצאה דורסה שם ואוכלה ומניח שם עור ופרש, וכמו כן רמז יעקב שני עניינים באומרו טריפה כנגד זאב, לא הבאתי כנגד ארי שמניח עור ופרש שמניח בדרסה, ואמר **אנכי אחטנה** כנגד גדר שהוא חייב בו שהוא טריפת זאב כגון זאב אחד שאינו אונס וחייב שומר שכר, (ב''מ ע''ב) ואמר **מידי תבקשנה** כנגד גדר ב' שהוא דרוסת ארי שאין חיוב על יעקב לשלם שהוא אונס ופטור אלא שהרשע היה מתאלם עליו ומבקש גם את זאת מיעקב, וכפי זה נזרקה רוה''ק בדברי רש''י ז''ל שכתב וז''ל טריפה וכו' על ידי ארי וזאב ע''כ, ויכוין לדברינו ונכון. ואומרו **גנובתי יום** וגו' נתכוון גם כן בענין נזקי בני אדם שהיה משלם בין מה שהוא חייב השומר שכר בין מה שאינו חייב, והוא אומרו גנובתי יום וגנובתי לילה פי' גנובתי הגניבה לי היתה מגעת גם בצד הפטור:
@133 **לולי אלהי אבי וגו'**. טעם שלא הספיק לומר אלהי אבי אברהם, נתכוין לומר ב' עניינים, אחד להיותו אלהי אבי עמד לי והצילני מידך בזכות אבי. והב' להיותו בעל היכולת ומשגיח ושופט בצדק ומציל עשוק, והוא אומרו **אלהי אברהם** פי' אלהי שפירסם אלהותו ואמיתתו אברהם והודיע בעולם נוראותיו אשר הוא הבורא הוא המשפיע ושופט בצדק, וזולת זה אם היה לאבי אלהי אחר לא היה מציל מידך כי כמה אלוהות יש שלא יועילו לעובדיהם אין כאלהינו ברוך הוא:
@133 **עוד** יכוין לומר על זה הדרך **אלהי אבי** כנגד זכות אבות ואחר כך הזכיר ב' מדות שהיו לו שעמדו לו שהם מדת החסד ומדת הדין כנגד מדת החסד אמר **אלהי אברהם** כאומרו (מיכה ז') חסד לאברהם, וכנגד מדת הדין אמר **ופחד יצחק**, ולזה לא אמר אלהי יצחק לרמוז על המדה שנתכוין לה, וזולת זה היה אומר אלהי יצחק שהרי מצינו שה' אמר לו (כ''ח י''ג) אלהי יצחק. וטעם שהזכיר ב' מדות אלו לומר כי הפליא חסדו עמו וגם עשה לו משפט עם לבן שהם ב' מדות וזולת אחד מהם לא היה מגיעו הטוב ליעקב:
@133 **את עניי וגו'**. פי' שאם לא היה לו העוני הגם שהיה האמת אתו היה ה' מאריך אפו ולתת לו שכרו לעולם העליון, ולצד עניו קיים לו ה' (דברים כד טו) ביומו תתן שכרו ונתן לו יגיע כפו:
@134 **ויען לבן וגו'**. אומרו ויען תשובה לאומרו שים כה נגד וגו' ויוכיחו, לזה ענה כי אינו חפץ להכלים בניו ובנותיו ולא יעמוד למשפט עמהם, והן הן רמאותיו לומר כי יוכיח שהאמת אתו אלא שאינו עושה לצד כבוד בניו ובנותיו:
@134 **עוד** רמז שאיך יצטדק בטענתו כשיאמר כלי ביתי הם אלו פשיטא שיותר ידע יעקב בסימני כלי לבן ממנו, והטעם כי הבנות בנותי והם בקיאים בסימני הכלים וכדומה יותר ממני להיותם תמיד משתמשים בהם:
@134 **עוד** ירצה להשיב על שמשש כל כליו כי לצד שהכל הוא מחשיבו כאילו שלו לצד שהבנות בנותיו וגו' והכל שלו היה עושה כאדם העושה בשלו כי אילו היה מחשיב אותו לאיש נכרי לא היה עושה כן:
@134 **ולבנותי וגו' לאלה וגו'**. תיבת לאלה אין לה משמעות. ואולי שחוזר אל כל אשר אתה רואה, ושיעור הכתוב הוא על זה הדרך ולבנותי פי' ולצד **בנותי מה אעשה** מהרע והגם שהן חושבים עצמן לנכרים ועוקרים מהם שם בנותי, והוא אומרו **לאלה היום** פי' שהיום נקראים אצלי אלה לצד מעשיהן אף על פי כן בנותי הם:
@134 **לבניהן אשר ילדו**. דקדק לומר אשר ילדו, שלא ליחם הבנים אחר אמם לזה אמר אשר ילדו לומר כי מה שקורא אותם בניהם לא ליחסם אחריהם כי למשפחותם לבית אבותם אלא לצד שילדו אותם קרא להם שם בניהם, והגם שהם דברי לבן, עם כל זה התורה תלמד דינים באמצעות הסיפורים. כמו שתמצא שלמדו (ירושלמי מוע''ק פ''א) מנין שאין מערבין שמחה בשמחה דכתיב מלא שבוע זאת וגו' הגם שהם דברי לבן:
@147 **ויפגעו בו מלאכי וגו'**. צריך לדעת כוונת אומרו **ויפגעו בו**. גם אומרו **ויאמר יעקב** וגו' מה חידוש מודיע הכתוב שאמר יעקב כן. גם יעקב מה חידש בדבריו. גם אין ידוע כוונת אומרו **מחנים**. ורז''ל (ב''ר פ' ע''ד) דרשו יעויין שם דבריהם שהוא דרש. ופשט הכתוב הוא, להיות כי שלח ה' מלאכים בדמות אנשים להדמות לפני עשו כאשר הוכיח סוף המעשה, לזה הקדים להודיע המעשה שממנו הרגיש יעקב היותם מלאכים, ואמר שלא בא המחנה כדרך האנשים שקודם יהיו נראים הלוך וקרב עד שיגיעו אצל הבאים אצלו אלא תיכף ומיד צמחו לפניו, והוא אומרו **ויפגעו בו** פי' ראיה ראשונה היתה הפגיעה בו אצלו, ויאמר יעקב כאשר ראם בדרך זה מחנה אלהים, אין אלה אנשים אלא מלאכים, ויקרא שם המקום מחנים פי' ב' מחנות אחד של אנשיו שהיו עמו לערוך מלחמה והב' של מלאכים בדמות אנשים כי באו לעזרת ה' לידידו יעקב בחיר ה':
@147 **חסלת פרשת ויצא**
